// ta translations of Legal Dictionary definitions, keyed by term id (see src/data/legalDictionary.ts).
// Only entries present here override the English definition for this language; any term id
// missing from this map falls back to its English definition. Usage examples stay English-only.
export const definitions: Record<string, string> = {
  // ─── General Procedure ───────────────────────────────────────────
  'plaint': 'ஒரு சிவில் வழக்கைத் தொடங்க ஒரு நபர் நீதிமன்றத்தில் தாக்கல் செய்யும் எழுத்து வடிவ ஆவணம். இதில் தரப்பினர் யார் என்பதும், என்ன நடந்தது என்பதும், நீதிமன்றம் என்ன உத்தரவு பிறப்பிக்க வேண்டும் என அந்த நபர் கோருகிறார் என்பதும் விவரிக்கப்பட்டிருக்கும்.',
  'written-statement': 'ஒரு சிவில் வழக்கில் பிரதிவாதி தாக்கல் செய்யும் முறையான எழுத்துப்பூர்வ பதில், இது வாதப் பத்திரத்தில் முன்வைக்கப்பட்ட கூற்றுகளுக்குப் பதிலளிக்கிறது. இதில் எந்தக் குற்றச்சாட்டுகள் ஒப்புக்கொள்ளப்படுகின்றன, எவை மறுக்கப்படுகின்றன என்று கூறப்படுவதுடன், பிரதிவாதியின் சொந்த வாதங்களையும் இதில் முன்வைக்கலாம்.',
  'affidavit': 'ஒரு நபர் உண்மைகளை எழுத்துப்பூர்வமாகக் கூறி, அவை உண்மை என்று ஒரு நோட்டரி, சத்திய வாக்குமூல ஆணையர், அல்லது வேறு அங்கீகரிக்கப்பட்ட அதிகாரி முன் கையெழுத்திட்டுச் சத்தியம் செய்யும் ஆவணம். பல நடைமுறைச் சூழல்களில், அந்த உண்மைகளை நபர் நேரில் மீண்டும் கூற வேண்டிய அவசியமில்லாமல், நீதிமன்றங்கள் இதை ஏற்றுக்கொள்கின்றன.',
  'decree': 'ஒரு சிவில் வழக்கில் தரப்பினரின் உரிமைகளை, தகராறான விஷயங்களில் முடிவாகத் தீர்த்து வைக்கும் நீதிமன்றத்தின் முறையான, இறுதி முடிவு. நடைமுறை அல்லது இடைக்கால விஷயங்களைக் கையாளும் "உத்தரவு" (order) என்பதிலிருந்து இது வேறுபட்டது; உத்தரவு பொதுவாக வழக்கை இறுதியாக முடிவு செய்வதில்லை.',
  'judicial-order': 'ஒரு வழக்கின் போது, ஒத்திவைப்பு வழங்குவது அல்லது ஒரு ஆவணத்தை ஏற்றுக்கொள்வது போன்ற நடைமுறை அல்லது இடைக்கால விஷயங்களில் நீதிமன்றம் பிறப்பிக்கும் முறையான வழிகாட்டுதல். தீர்ப்பாணையைப் போலல்லாமல், ஒரு உத்தரவு வழக்கையோ அதில் உள்ள ஒரு அடிப்படை உரிமையையோ இறுதியாகத் தீர்க்க வேண்டும் என்பதில்லை.',
  'ex-parte': 'ஒரு தரப்பினர் மட்டும் ஆஜராக இருக்கும்போது நடத்தப்படும் விசாரணை அல்லது பிறப்பிக்கப்படும் உத்தரவு, பொதுவாக அறிவிப்பு அனுப்பப்பட்டிருந்தும் மற்ற தரப்பினர் ஆஜராகாததால் ஏற்படுகிறது. ஆஜராகாத தரப்பினர் விசாரணையில் கூடாததற்குப் போதிய காரணம் காட்டினால், ex parte உத்தரவை பெரும்பாலும் எதிர்த்து வாதிடவோ ரத்து செய்யவோ முடியும்.',
  'limitation-period': 'வழக்குத் தொடரும் அல்லது குறிப்பிட்ட சட்ட நடவடிக்கை எடுக்கும் உரிமை முதலில் எழுந்த நாளிலிருந்து கணக்கிடப்படும், அதற்குள் ஒரு நபர் வழக்கைத் தாக்கல் செய்ய வேண்டிய கால வரம்பு. தாமதத்திற்குச் சரியான காரணம் இல்லாமல் இந்தக் காலத்திற்குப் பிறகு வழக்கு தாக்கல் செய்யப்பட்டால், வழக்கின் தகுதியைப் பொருட்படுத்தாமல், நீதிமன்றங்கள் அதை விசாரிக்கவே மறுக்கலாம்.',
  'cause-of-action': 'ஒரு நபருக்கு வேறொருவர் மீது வழக்குத் தொடரும் சட்ட உரிமையை அளிக்கும் உண்மைகளின் தொகுப்பு. உண்மையான வழக்குக் காரணம் இருந்து, அது தெளிவாகக் கூறப்பட்டால் மட்டுமே வழக்கைத் தாக்கல் செய்ய முடியும்; அப்படி இல்லையெனில் நீதிமன்றம் அதை விசாரிக்காது.',
  'jurisdiction': 'வழக்கின் பொருள், கோரப்படும் தொகையின் மதிப்பு, தரப்பினர் அல்லது சொத்து அமைந்துள்ள இடம் போன்ற காரணிகளின் அடிப்படையில், ஒரு குறிப்பிட்ட நீதிமன்றம் அல்லது தீர்ப்பாயம் ஒரு வழக்கை விசாரித்துத் தீர்ப்பளிக்கும் அதிகாரம். அதிகார வரம்பு இல்லாத தவறான மன்றத்தில் வழக்கு தாக்கல் செய்யப்பட்டால், வழக்கின் தகுதியைப் பொருட்படுத்தாமல் அது தள்ளுபடி செய்யப்படலாம் அல்லது மாற்றப்படலாம்.',
  'locus-standi': 'ஒரு விஷயத்தால் நேரடியாகப் பாதிக்கப்பட்டிருப்பதால், அதற்கான வழக்கைத் தொடரவோ அதில் விசாரிக்கப்படவோ ஒரு நபருக்கு உள்ள சட்ட உரிமை. locus standi இல்லாத ஒருவரின் அடிப்படைக் குறை உண்மையானதாக இருந்தாலும், அவரை விசாரிக்க நீதிமன்றம் மறுக்கலாம்.',
  'adjournment': 'ஒரு நீதிமன்ற விசாரணையை பிந்தைய தேதிக்கு ஒத்திவைப்பது, பொதுவாக தயாராக மேலும் நேரம் தேவை அல்லது வழக்கறிஞர் கிடைக்காமை போன்ற சரியான காரணத்திற்காக தரப்பினர் ஒருவரின் கோரிக்கையின் பேரில் வழங்கப்படும்.',
  'stay-order': 'மேலும் உத்தரவு வரும் வரை, ஒரு குறிப்பிட்ட நடவடிக்கையையோ, நடைமுறையையோ, அல்லது கீழமை நீதிமன்ற உத்தரவின் செயல்பாட்டையோ தற்காலிகமாக நிறுத்தி வைக்கும் நீதிமன்றம் அல்லது தீர்ப்பாயத்தின் உத்தரவு. உதாரணமாக, ஒரு தீர்ப்பாணைக்கு எதிரான மேல்முறையீடு நிலுவையில் இருக்கும்போது, அந்தத் தீர்ப்பாணையை அமல்படுத்துவதை நீதிமன்றம் தடை செய்யலாம்.',
  'condonation-of-delay': 'வரம்பு காலம் முடிந்தபிறகு ஒரு வழக்கையோ மேல்முறையீட்டையோ தாக்கல் செய்த தரப்பினரை மன்னிக்கும் நீதிமன்ற உத்தரவு, தாமதத்திற்குப் போதுமான, உண்மையான காரணத்தைக் காட்டும்போது வழங்கப்படும். இது இல்லாவிட்டால், தாமதமான தாக்கல் பொதுவாக உடனடியாக நிராகரிக்கப்படும்.',
  'interlocutory-application': 'முதன்மை வழக்கு இன்னும் நிலுவையில் இருக்கும்போது, அதன் இறுதி முடிவுக்காக அல்லாமல், ஒரு இடைக்கால உத்தரவு அல்லது வழிகாட்டுதலுக்காக நீதிமன்றம் அல்லது தீர்ப்பாயத்திடம் செய்யப்படும் கோரிக்கை. இடைக்கால தடை உத்தரவு, தாமதத்திற்கு மன்னிப்பு, அல்லது மனுவில் திருத்தம் செய்ய அனுமதி கோரும் விண்ணப்பங்கள் இதன் பொதுவான உதாரணங்கள்.',
  'show-cause-notice': 'ஒரு நபர் அல்லது நிறுவனத்திற்கு எதிராக ஒரு குறிப்பிட்ட நடவடிக்கை ஏன் எடுக்கப்படக்கூடாது என்பதை, குறிப்பிட்ட காலத்திற்குள் விளக்கமளிக்குமாறு கேட்கும் முறையான அறிவிப்பு. பாதகமான முடிவு எடுக்கப்படுவதற்கு முன் பதிலளிக்க வாங்குபவருக்கு வாய்ப்பளிக்கிறது.',
  'interim-order': 'ஒரு வழக்கு நடந்துகொண்டிருக்கும்போது, வழக்கு இறுதியாகத் தீரும் வரை நிலைமையைப் பாதுகாக்கவோ தரப்பினரின் நலன்களைக் காக்கவோ நீதிமன்றம் பிறப்பிக்கும் தற்காலிக உத்தரவு. இது தகராறின் தகுதி மீதான தீர்ப்பு அல்ல.',
  'summary-suit': 'குறிப்பிட்ட வகைக் கோரிக்கைகளுக்குப் பயன்படுத்தப்படும் விரைவான சிவில் நடைமுறை, பொதுவாக செலுத்தப்படாத பில் அல்லது எழுத்துப்பூர்வ ஒப்பந்தத்தின் கீழ் உள்ள கடன் போன்ற தெளிவான, நிலையான தொகையை மீட்பதற்கானது. வழக்கை எதிர்த்து வாதிடும் பிரதிவாதியின் தானியங்கு உரிமையை இது கட்டுப்படுத்தி, வாதம் உண்மையாக இருக்க வாய்ப்பில்லாத வழக்குகளை விரைவுபடுத்துகிறது.',
  'caveat': 'மற்ற தரப்பினரிடமிருந்து எதிர்பார்க்கப்படும் விண்ணப்பத்தின் மீது, எடுத்துக்காட்டாக ஒரு ex parte தடை உத்தரவு, எந்த உத்தரவும் பிறப்பிக்கப்படுவதற்கு முன் தனக்குத் தெரியப்படுத்தி விசாரிக்கப்பட வேண்டும் என்று நீதிமன்றத்தில் தாக்கல் செய்யப்படும் முறையான அறிவிப்பு. ஒரு caveat தாக்கல் செய்யப்பட்டதும், அதைத் தாக்கல் செய்தவருக்கு முதலில் விசாரிக்கப்பட வாய்ப்பு அளிக்க நீதிமன்றம் கடமைப்பட்டுள்ளது.',
  'plaintiff': 'பிரதிவாதிக்கு எதிராக ஏதேனும் நிவாரணம் வழங்குமாறு நீதிமன்றத்தைக் கேட்டு சிவில் வழக்கைத் தாக்கல் செய்பவர்.',
  'defendant': 'ஒரு சிவில் வழக்கு தாக்கல் செய்யப்பட்ட நபர், வாதியின் கூற்றுகளுக்கு எழுத்துப்பூர்வ பதில் தாக்கல் செய்து பதிலளிக்குமாறு கேட்கப்படுபவர்.',
  'petitioner': 'ஒரு மனுவைத் தாக்கல் செய்பவர்; ரிட் மனுக்கள், திருமண வழக்குகள், அல்லது நிறுவனச் சட்ட நடவடிக்கைகள் போன்ற விஷயங்களில் "வாதி" என்பதற்குப் பதிலாக இந்தச் சொல் பயன்படுத்தப்படுகிறது.',
  'respondent': 'ஒரு மனு, மேல்முறையீடு, அல்லது மறுபரிசீலனை தாக்கல் செய்யப்பட்ட நபர், அதற்குப் பதிலளிக்குமாறு கேட்கப்படுபவர்; ஒரு வழக்கில் பிரதிவாதி ஏற்கும் பங்கையே இத்தகைய நடவடிக்கைகளில் இவர் ஏற்கிறார்.',
  'appellant': 'கீழமை நீதிமன்றம் அல்லது தீர்ப்பாயத்தின் முடிவை எதிர்த்து மேல்முறையீடு தாக்கல் செய்பவர்; அந்த முடிவை ஆதரித்து வாதிடும் எதிர்மனுதாரரிடமிருந்து இவர் வேறுபடுகிறார்.',
  'applicant': 'நீதிமன்றம் அல்லது தீர்ப்பாயத்திடமிருந்து ஒரு குறிப்பிட்ட உத்தரவு அல்லது வழிகாட்டுதலைக் கோரி விண்ணப்பம் தாக்கல் செய்பவர்; இடைக்கால விண்ணப்பங்களிலும், NCLT அல்லது நுகர்வோர் ஆணையம் போன்ற தீர்ப்பாயங்களின் முன் நடவடிக்கைகளிலும் இந்தச் சொல் பெரும்பாலும் பயன்படுத்தப்படுகிறது.',
  'dismissal-for-default': 'பொதுவாக வாதி அல்லது மேல்முறையீட்டாளரான ஒரு தரப்பினர், அனுமதிக்கப்பட்ட காலத்திற்குள் ஆஜராகவோ, நீதிமன்றக் கட்டணம் செலுத்துதல் அல்லது ஆவணங்கள் தாக்கல் செய்தல் போன்ற தேவையான நடவடிக்கை எடுக்கவோ தவறியதால், வழக்கை முடித்து வைக்கும் உத்தரவு. இது வழக்கின் தகுதி மீதான முடிவு அல்ல.',
  'restoration-of-suit': 'இயல்புநிலைத் தவறுக்காக தள்ளுபடி செய்யப்பட்ட ஒரு வழக்கை மீண்டும் உயிர்ப்பிக்குமாறு நீதிமன்றத்தைக் கோரும் விண்ணப்பம், பொதுவாக முன்பு ஆஜராகாததற்கோ கட்டுப்படாததற்கோ போதுமான காரணத்தைக் காட்டி செய்யப்படும். அனுமதிக்கப்பட்டால், வழக்கு தள்ளுபடி செய்யப்பட்ட இடத்திலிருந்து தொடரும்.',
  'transfer-petition': 'நிலுவையிலுள்ள ஒரு வழக்கை ஒரு நீதிமன்றத்திலிருந்தோ தீர்ப்பாயத்திலிருந்தோ வேறொன்றுக்கு மாற்றுமாறு மேல் நீதிமன்றத்தைக் கோரும் மனு, பொதுவாக தரப்பினரின் வசதி, நியாயமான விசாரணையை உறுதி செய்தல், அல்லது தொடர்புடைய வழக்கு ஏற்கெனவே வேறு நீதிமன்றத்தில் இருப்பது போன்ற காரணங்களுக்காக தாக்கல் செய்யப்படும்.',
  'pecuniary-jurisdiction': 'கோரப்படும் தொகையின் பண மதிப்பின் அடிப்படையிலேயே ஒரு வழக்கை விசாரிக்கும் நீதிமன்றத்தின் அதிகாரம். நீதிமன்றங்களுக்கும் தீர்ப்பாயங்களுக்கும் பொதுவாக மதிப்பு வரம்புகள் நிர்ணயிக்கப்பட்டிருக்கும்; அதனால் நிர்ணயிக்கப்பட்ட வரம்புக்கு மேலோ கீழோ உள்ள கோரிக்கை வேறொரு மன்றத்தில் தாக்கல் செய்யப்பட வேண்டும்.',
  'substituted-service': 'ஒரு தரப்பினருக்கு அறிவிப்பு அல்லது சம்மன்களை நேரடியாகவோ தனிநபர் முன்னிலையிலோ வழங்க முடியாதபோது பயன்படுத்தப்படும் மாற்று வழிமுறை, எடுத்துக்காட்டாக அறிவிப்பை செய்தித்தாளில் வெளியிடுதல் அல்லது தரப்பினரின் கடைசியாகத் தெரிந்த முகவரியில் ஒட்டுதல்.',
  'court-fee': 'ஒரு வாதப் பத்திரம், மனு, அல்லது மேல்முறையீடு தாக்கல் செய்யப்படுவதற்கு முன் அரசுக்குச் செலுத்த வேண்டிய கட்டணம், பொதுவாக முத்திரைத் தாள் அல்லது ஆன்லைன் பணம் செலுத்துதல் மூலம். இது பொதுவாக வழக்கில் கோரப்படும் தொகை அல்லது மதிப்பின் சதவீதமாகக் கணக்கிடப்படும், சில வகை தாக்கல்களுக்கு உச்சவரம்புக்கு உட்பட்டது.',
  'next-friend': 'ஒரு சிறுபிள்ளை தனது பெயரில் வழக்குத் தொடர முடியாததால், அந்தச் சிறுபிள்ளை வாதியாக இருக்கும் சிவில் வழக்கை, அவருக்காகத் தாக்கல் செய்து நடத்தும் பொறுப்புள்ள பெரியவர், பொதுவாக பெற்றோர் அல்லது நெருங்கிய உறவினர்.',

  // ─── Pleadings & Documents ────────────────────────────────────────
  'petition': 'ஒரு குறிப்பிட்ட நடவடிக்கை எடுக்குமாறு நீதிமன்றம் அல்லது தீர்ப்பாயத்தைக் கோரும் முறையான எழுத்துப்பூர்வ வேண்டுகோள்; ரிட்கள், நிறுவனச் சட்ட வழக்குகள், திருமண வழக்குகள், அல்லது சில மன்றங்களுக்கான மேல்முறையீடுகள் போன்ற விஷயங்களில் வாதப் பத்திரத்திற்குப் பதிலாக இது பயன்படுத்தப்படுகிறது. மன்றம் மற்றும் வழக்கு வகையைப் பொறுத்து இதன் அமைப்பும் தேவைகளும் மாறுபடும்.',
  'memorandum-of-appeal': 'ஒரு மேல்முறையீட்டைத் தொடங்க தாக்கல் செய்யப்படும் முறையான ஆவணம், கீழமை நீதிமன்றம் அல்லது தீர்ப்பாயத்தின் முடிவை மேல்முறையீட்டாளர் எந்த அடிப்படையில் எதிர்க்கிறார் என்பதை விவரிக்கிறது. ஒவ்வொரு அடிப்படையும் பொதுவாக தனித்தனி எண் இட்ட புள்ளியாக பட்டியலிடப்பட்டு, முந்தைய முடிவில் என்ன தவறு இருந்தது என்பதை விளக்குகிறது.',
  'vakalatnama': 'ஒரு வழக்கில் தன்னைச் சார்பாக நீதிமன்றத்தில் பிரதிநிதித்துவம் செய்ய ஒரு குறிப்பிட்ட வழக்கறிஞர் அல்லது சட்ட நிறுவனத்திற்கு அதிகாரம் அளித்து வாடிக்கையாளர் கையெழுத்திடும் ஆவணம். வழக்கறிஞர் முறையாக ஆஜராகி வாடிக்கையாளரின் பெயரில் செயல்படுவதற்கு முன் இது தாக்கல் செய்யப்பட்டிருக்க வேண்டும்.',
  'index-of-documents': 'ஒரு நீதிமன்றத் தாக்கலின் தொடக்கத்தில் வைக்கப்படும் பட்டியல், அதில் உள்ள ஒவ்வொரு ஆவணத்தையும் பொதுவாக பக்க எண்களுடன் சுருக்கமாகக் காட்டுகிறது. தாக்கலில் உள்ள ஒரு குறிப்பிட்ட ஆவணத்தை நீதிமன்றமும் மற்ற தரப்பினரும் விரைவாகக் கண்டறிய இது உதவுகிறது.',
  'annexure': 'ஒரு மனு அல்லது வாதப் பத்திரத்தில் கூறப்பட்ட உண்மைகளை ஆதரிக்க அதனுடன் இணைக்கப்படும் ஒப்பந்தம், ரசீது, அல்லது கடிதம் போன்ற துணை ஆவணம். இணைப்புகள் பொதுவாக எழுத்துக்கள் அல்லது எண்களால் குறியிடப்பட்டு, முதன்மை ஆவணத்தில் அந்தக் குறியீட்டின் மூலமாகக் குறிப்பிடப்படும்.',
  'verification-clause': 'ஒரு மனுவின் இறுதியில் இருக்கும் குறுகிய, கையொப்பமிடப்பட்ட அறிக்கை, இதில் தாக்கல் செய்பவர் அதன் உள்ளடக்கம் தமக்குத் தெரிந்தவரை உண்மை என்றோ, உண்மை என்று தாம் நம்பும் தகவலின் அடிப்படையிலானது என்றோ உறுதிப்படுத்துகிறார். ஆவணத்தில் கூறப்பட்டவற்றுக்கு தாக்கல் செய்பவரைத் தனிப்பட்ட முறையில் பொறுப்பாக்குவதே இதன் நோக்கம்.',
  'cause-title': 'ஒரு நீதிமன்ற ஆவணத்தின் மேற்பகுதியில் இருக்கும் தலைப்பு, நீதிமன்றம், வழக்கு எண், மற்றும் சம்பந்தப்பட்ட தரப்பினரைக் குறிப்பிடுகிறது, பொதுவாக "வாதி எதிராக பிரதிவாதி" என எழுதப்பட்டிருக்கும். இந்த ஆவணம் எந்த வழக்குக்கு சொந்தமானது என்பதை இது துல்லியமாக அடையாளப்படுத்துகிறது.',
  'prayer-clause': 'ஒரு மனு அல்லது வாதப் பத்திரத்தின் பகுதி, பொதுவாக இறுதியில் இருக்கும், எந்தக் குறிப்பிட்ட நிவாரணம் அல்லது உத்தரவை நீதிமன்றம் வழங்க வேண்டும் என நபர் கோருகிறார் என்பதைத் தெளிவாகக் கூறுகிறது. prayer clause-இல் குறிப்பாகக் கோரப்படாத நிவாரணத்தை நீதிமன்றங்கள் பொதுவாக வழங்குவதில்லை.',
  'schedule-to-document': 'ஒரு பத்திரம் அல்லது வாதப் பத்திரம் போன்ற சட்ட ஆவணத்தின் இறுதியில் இருக்கும் பகுதி, ஆவணத்தில் வேறிடத்தில் குறிப்பிடப்பட்ட விரிவான தகவலை, எடுத்துக்காட்டாக ஒரு சொத்தின் துல்லியமான விவரணையையும் எல்லைகளையும் தருகிறது. இந்த விவரத்தை தனி அட்டவணையில் (schedule) வைப்பது ஆவணத்தின் முதன்மை உள்ளடக்கத்தைப் படிக்க எளிதாக வைக்கிறது.',
  'rejoinder': 'வழக்கைத் தொடங்கிய தரப்பினர், எதிர்த் தரப்பினர் தாக்கல் செய்த எழுத்துப்பூர்வ பதில் அல்லது மறுமொழிக்குப் பதிலளிக்க தாக்கல் செய்யும் எழுத்துப்பூர்வ மறுமொழி. எழுப்பப்பட்ட புதிய புள்ளிகள் அல்லது வாதங்களுக்கு பதிலளிக்க இது அசல் தரப்பினருக்கு வாய்ப்பளிக்கிறது.',
  'counter-affidavit': 'ஒரு தரப்பினர், எதிர்த் தரப்பினர் தாக்கல் செய்த சத்தியப் பிரமாணப் பத்திரம் அல்லது விண்ணப்பத்திற்குப் பதிலளிக்க தாக்கல் செய்யும் சத்தியப் பிரமாணப் பத்திரம், அதில் கூறப்பட்ட உண்மைகள் மற்றும் கூற்றுகளை மறுத்து அல்லது அவற்றுக்குப் பதிலளிக்கிறது.',
  'legal-notice': 'பொதுவாக வழக்கறிஞர் மூலம் வேறொரு நபர் அல்லது நிறுவனத்திற்கு அனுப்பப்படும் முறையான எழுத்துப்பூர்வத் தொடர்பு, ஒரு குறையைத் தெரிவித்து, கூறப்பட்ட காலத்திற்குள் அது தீர்க்கப்படாவிட்டால் சட்ட நடவடிக்கை எடுக்கப்படும் என எச்சரிக்கிறது. சில வகை வழக்குகளைத் தாக்கல் செய்வதற்கு முன் இதை அனுப்புவது பெரும்பாலும் தேவையான அல்லது அறிவுறுத்தப்படும் நடவடிக்கையாகும்.',
  'written-submissions': 'ஒரு தரப்பினர், நீதிமன்றம் கருத்தில் கொள்ள வேண்டிய வாதங்களையும் சட்டப் புள்ளிகளையும் எழுத்துப்பூர்வமாக முன்வைக்கும் ஆவணம், பெரும்பாலும் வாய்மொழி வாதங்கள் முடிந்த பிறகோ, நீண்ட வாய்மொழி விசாரணைக்குப் பதிலாகவோ தாக்கல் செய்யப்படும். இறுதி முடிவை வரைவு செய்யும்போது நீதிமன்றங்கள் எழுத்துப்பூர்வ வாதங்களை அடிக்கடி மீண்டும் பார்க்கின்றன.',
  'certified-copy': 'ஒரு நீதிமன்ற உத்தரவு, தீர்ப்பு, அல்லது ஆவணத்தின் அதிகாரப்பூர்வ நகல், பதிவில் உள்ள மூலத்தின் உண்மையான, துல்லியமான நகல் என்பதை உறுதிப்படுத்த நீதிமன்றப் பதிவகத்தால் முத்திரையிடப்பட்டு கையொப்பமிடப்பட்டிருக்கும். மேல்முறையீடு தாக்கல் செய்யவோ, வேறிடத்தில் ஒரு ஆவணத்தின் உள்ளடக்கத்தை நிரூபிக்கவோ சான்றளிக்கப்பட்ட நகல்கள் பெரும்பாலும் தேவைப்படும்.',
  'memorandum-of-parties': 'ஒரு மனு அல்லது மேல்முறையீட்டின் தொடக்கத்தில் இருக்கும் பட்டியல், வழக்கில் உள்ள ஒவ்வொரு தரப்பினரையும் அவரவர் முகவரியுடன் பெயரிடுகிறது; இது குறுகிய cause title-இலிருந்து வேறுபட்டது. உயர் நீதிமன்றங்கள் மற்றும் உச்ச நீதிமன்றம் முன் தாக்கல் செய்யப்படும் தாக்கல்கள் போன்ற, தரப்பினரின் முழு விவரங்களை தனியாக வைக்க வேண்டிய தாக்கல்களில் இது பயன்படுத்தப்படுகிறது.',
  'synopsis-and-list-of-dates': 'வழக்கின் பின்னணியின் குறுகிய சுருக்கம், முக்கிய நிகழ்வுகள் மற்றும் அவற்றின் தேதிகளின் காலவரிசை அட்டவணையுடன் சேர்த்து, உயர் நீதிமன்றங்கள் மற்றும் உச்ச நீதிமன்றத்தில் மனுக்களின் தொடக்கத்தில் தாக்கல் செய்யப்படுவது. முழு மனுவையும் படிப்பதற்கு முன் வழக்கின் வரலாற்றை நீதிபதி விரைவாகப் புரிந்துகொள்ள இது உதவுகிறது.',
  'written-version': 'நுகர்வோர் ஆணையம் முன் உள்ள வழக்கில் எதிர் தரப்பினர் தாக்கல் செய்யும் முறையான எழுத்துப்பூர்வ பதில், புகாரில் கூறப்பட்ட குற்றச்சாட்டுகளுக்குப் பதிலளிக்கிறது. ஒரு வழக்கமான சிவில் வழக்கில் எழுத்துப்பூர்வ பதில் செய்யும் பணியையே இது அங்கு செய்கிறது.',
  'memorandum-of-appearance': 'NCLT போன்ற சில தீர்ப்பாயங்கள் முன் தாக்கல் செய்யப்படும் ஆவணம், இதன் மூலம் ஒரு தரப்பினரின் அங்கீகரிக்கப்பட்ட பிரதிநிதி ஒரு வழக்கில் முறையாக ஆஜராகிறார்; நீதிமன்றம் முன் தாக்கல் செய்யப்படும் வக்காலத்நாமா செய்யும் பணிக்கு ஒப்பானது இது.',
  'affidavit-of-service': 'ஒரு அறிவிப்பு, சம்மன், அல்லது வேறு ஆவணத்தை மற்றொரு தரப்பினருக்கு வழங்கிய நபர் தாக்கல் செய்யும் சத்தியப் பிரமாணப் பத்திரம், அது எப்போது, எப்படி, யாருக்கு வழங்கப்பட்டது என்பதை உறுதிப்படுத்துகிறது. முறையான வழங்கல் நடந்துள்ளது என்று திருப்தி அடைய நீதிமன்றங்கள் இதை நம்பியிருக்கின்றன.',
  'list-of-witnesses': 'ஆதாரம் தொடங்குவதற்கு முன் ஒரு தரப்பினர் தாக்கல் செய்யும் பட்டியல், தமது வழக்கை நிரூபிக்க முன்வைக்க உத்தேசிக்கும் சாட்சிகளைப் பெயரிடுகிறது. யார் விசாரிக்கப்படுவார்கள் என்பதை நீதிமன்றமும் மற்ற தரப்பினரும் முன்கூட்டியே அறிய இது உதவுகிறது.',
  'paper-book': 'ஒரு வழக்கில் உள்ள தொடர்புடைய அனைத்து மனுக்கள், ஆவணங்கள், மற்றும் உத்தரவுகளின் தொகுக்கப்பட்ட தொகுப்பு, ஒன்றாகக் கட்டி அட்டவணையிடப்பட்டு, முதன்மையாக மேல் நீதிமன்றங்கள் மற்றும் தீர்ப்பாயங்கள் முன் மேல்முறையீடுகள் மற்றும் விசாரணைகளுக்குப் பயன்படுத்த தயாரிக்கப்படும்.',
  'supplementary-affidavit': 'ஒரு தரப்பினர், தமது அசல் சத்தியப் பிரமாணப் பத்திரத்திற்குப் பிறகு, முன்பு சேர்க்கப்படாத புதிய உண்மைகள், ஆவணங்கள், அல்லது வளர்ச்சிகளை நீதிமன்றத்தின் முன் வைக்க, முற்றிலும் புதிய விண்ணப்பம் தாக்கல் செய்வதற்குப் பதிலாக தாக்கல் செய்யும் கூடுதல் சத்தியப் பிரமாணப் பத்திரம்.',
  'amendment-of-pleadings': 'ஏற்கெனவே தாக்கல் செய்யப்பட்ட வாதப் பத்திரம் அல்லது எழுத்துப்பூர்வ பதிலில், ஒரு உண்மை அல்லது நிவாரணம் சேர்ப்பது போன்ற திருத்தம் அல்லது சேர்த்தல் செய்ய ஒரு தரப்பினருக்கு நீதிமன்றம் வழங்கும் அனுமதி. வழக்கின் தன்மையை அடிப்படையில் மாற்றாத வரையில், நீதிமன்றங்கள் பொதுவாக இதை அனுமதிக்கின்றன.',
  'undertaking': 'ஒரு தரப்பினர் ஒரு குறிப்பிட்ட செயலைச் செய்வார் அல்லது செய்ய மாட்டார் என நீதிமன்றத்திடம் செய்யப்படும் முறையான உறுதிமொழி, இது வாய்மொழியாகச் சொல்லப்பட்டு உத்தரவில் பதிவு செய்யப்படலாம் அல்லது சத்தியப் பிரமாணப் பத்திரம் மூலமாகவும் செய்யப்படலாம். நீதிமன்றத்திடம் கொடுக்கப்பட்ட உறுதிமொழியை மீறுவதே நீதிமன்ற அவமதிப்பாக ஆகலாம்.',
  'notice-of-motion': 'முதன்மையாக சில உயர் நீதிமன்றங்களின் மூல சிவில் அதிகார வரம்பில் தாக்கல் செய்யப்படும் முறையான அறிவிப்பு, இடைக்கால நிவாரணத்திற்கான விண்ணப்பம் ஒரு குறிப்பிட்ட தேதியில் நீதிமன்றத்தில் முன்வைக்கப்படும் என எதிர் தரப்பினருக்குத் தெரிவிக்கிறது.',
  'reply-to-legal-notice': 'ஒரு சட்ட அறிவிப்பைப் பெற்றவர், எந்த வழக்கும் தாக்கல் செய்யப்படுவதற்கு முன், அதில் முன்வைக்கப்பட்ட கூற்றுகளை ஏற்றுக்கொண்டோ, மறுத்தோ, அல்லது விளக்கமளித்தோ, தமது சொந்த வழக்கறிஞர் மூலம் அனுப்பும் எழுத்துப்பூர்வ பதில்.',
  'compilation-of-judgments': 'ஒரு வழக்கில் முன்வைக்கப்படும் சட்ட வாதங்களுக்கு ஆதரவாக, ஒரு தரப்பினர் நம்பியிருந்து நீதிமன்றத்தில் தாக்கல் செய்யும், முன்பே தீர்க்கப்பட்ட தீர்ப்புகளின் கட்டப்பட்ட தொகுப்பு.',

  // ─── Evidence ─────────────────────────────────────────────────────
  'examination-in-chief': 'ஒரு சாட்சியை சாட்சியம் அளிக்க அழைத்த தரப்பின் வழக்கறிஞர் நடத்தும் முதல் கட்ட கேள்வி கேட்டல். அந்தத் தரப்பின் வழக்கை ஆதரிக்கும் உண்மைகளை வெளிக்கொணர்வதே இதன் நோக்கம்.',
  'cross-examination': 'examination-in-chief முடிந்தபிறகு, எதிர்த் தரப்பின் வழக்கறிஞர் சாட்சியிடம் கேள்வி கேட்பது. சாட்சியின் விவரணையைச் சோதித்து, பலவீனங்களையோ முரண்பாடுகளையோ வெளிக்கொணர்ந்து, அவரது நம்பகத்தன்மையை எதிர்த்து வாதிடுவதே இதன் நோக்கம்.',
  're-examination': 'சாட்சியை முதலில் அழைத்த தரப்பினர், cross-examination முடிந்தபிறகு நடத்தும் மேலும் ஒரு கட்ட கேள்வி கேட்டல், இது cross-examination-இல் எழுந்த புள்ளிகளைத் தெளிவுபடுத்துவதற்கு மட்டும் வரையறுக்கப்பட்டது.',
  'hearsay': 'ஒரு சாட்சி நேரில் கண்டதையோ அனுபவித்ததையோ அல்லாமல், வேறொருவர் தமக்குச் சொன்னதைப் பற்றி நீதிமன்றத்தில் கூறும் அறிக்கை. hearsay பொதுவாக நம்பகமான ஆதாரமாகக் கருதப்படுவதில்லை, எனினும் அது ஏற்றுக்கொள்ளப்படக்கூடிய அங்கீகரிக்கப்பட்ட விதிவிலக்குகள் உள்ளன.',
  'burden-of-proof': 'ஒரு தரப்பினர் தாம் கூறும் உண்மைகளை நிரூபிக்க வேண்டிய ஒட்டுமொத்த சட்டக் கடமை; எந்த ஆதாரமும் முன்வைக்கவில்லை எனில், அந்தப் புள்ளியில் அவர் தோற்கிறார். பெரும்பாலான சிவில் மற்றும் குற்றவியல் வழக்குகளில், இந்தப் பொறுப்பு ஆரம்பத்திலேயே சட்டத்தால் நிர்ணயிக்கப்பட்டு, பொதுவாக மற்ற தரப்பினருக்கு மாறுவதில்லை.',
  'deposition': 'examination-in-chief, cross-examination, மற்றும் re-examination-இன் போது பதிவு செய்யப்படும், ஒரு சாட்சியின் சத்தியமிட்ட சாட்சியத்தின் முறையான பதிவு. வழக்கைத் தீர்மானிக்கும்போது நீதிமன்றம் நம்பியிருக்கும் அதிகாரப்பூர்வ வழக்குப் பதிவின் ஒரு பகுதியாக இது ஆகிறது.',
  'exhibit-evidence': 'ஒரு வழக்கின் போது முறையாக ஆதாரமாக ஏற்கப்பட்ட ஆவணம் அல்லது பொருள், பின்னர் அடையாளம் காண ஒரு குறியீட்டு எண் அல்லது எழுத்துடன் குறியிடப்பட்டிருக்கும். exhibit ஆக குறியிடப்பட்டதும், வழக்கின் மற்ற கட்டங்கள் முழுவதும் நீதிமன்றமும் இரு தரப்பினரும் அந்தக் குறியீட்டின் மூலமாக அதைக் குறிப்பிடலாம்.',
  'documentary-evidence': 'ஒப்பந்தங்கள், கடிதங்கள், ரசீதுகள், அல்லது மின்னணு பதிவுகள் போன்ற எழுத்துப்பூர்வ அல்லது பதிவு செய்யப்பட்ட பொருள் வடிவிலான ஆதாரம், ஒரு வழக்கில் ஒரு உண்மையை நிரூபிக்க முன்வைக்கப்படுகிறது. சாட்சி நேரில் அளிக்கும் சாட்சியமான வாய்மொழி ஆதாரத்திலிருந்து இது வேறுபட்டது.',
  'oral-evidence': 'நீதிமன்றத்தின் முன் சாட்சி நேரடியாகப் பேசி அளிக்கும் ஆதாரம், பொதுவாக சத்தியமிட்ட பின்; எழுத்துப்பூர்வ அல்லது பதிவு வடிவிலான ஆவண ஆதாரத்திற்கு மாறாக இது இருக்கும். வாய்மொழி ஆதாரம் பொதுவாக examination-in-chief, cross-examination, மற்றும் re-examination மூலம் பெறப்பட்டு பதிவு செய்யப்படும்.',
  'admission-evidence': 'ஒரு தரப்பினர், வாய்மொழியாகவோ, எழுத்துப்பூர்வமாகவோ, அல்லது நடத்தை மூலமாகவோ, தமது வழக்கிற்கு எதிரான ஒரு உண்மையை ஒப்புக்கொள்ளும் அறிக்கை. தமது சொந்த வழக்கைப் பாதிக்கும் பொருளற்ற ஒன்றை ஒருவர் ஒப்புக்கொள்ள வாய்ப்பில்லை என்பதால், நீதிமன்றங்கள் admission-ஐ வலுவான ஆதாரமாகக் கருதுகின்றன.',
  'onus-of-proof': 'ஒரு விசாரணையின் குறிப்பிட்ட கட்டத்தில், ஒரு குறிப்பிட்ட பிரச்சினை மீது ஆதாரம் முன்வைக்க வேண்டிய கடமை, இது ஒட்டுமொத்த burden of proof-இலிருந்து வேறுபட்டது. burden of proof போலல்லாமல், ஒரு புள்ளி மீது ஒவ்வொரு தரப்பும் ஆதாரம் முன்வைக்கும் அல்லது முன்வைக்கத் தவறும் அளவுக்கேற்ப, onus தரப்பினருக்கு இடையே முன்னும் பின்னும் மாறலாம்.',
  'hostile-witness': 'சாட்சியம் அளிக்கும்போது, தம்மை அழைத்த தரப்பினரிடம் முன்பு கொடுத்த அறிக்கைக்கு முரணாகக் கூறும், அல்லது அந்த தரப்பின் வழக்கை ஆதரிக்க விரும்பாதவராகத் தோன்றும் சாட்சி. ஒரு சாட்சியை hostile என நீதிமன்றம் அறிவித்தவுடன், அவரை அழைத்த தரப்பினருக்கு, cross-examination போன்றே, அவரை நேரடியாக மேலும் விசாரிக்க அனுமதிக்கப்படலாம்.',
  'expert-opinion': 'மருத்துவர், குற்றவியல் ஆய்வாளர், அல்லது கையெழுத்து நிபுணர் போன்ற, ஒரு குறிப்பிட்ட துறையில் சிறப்புத் திறமையோ அறிவோ உள்ள நபரின் கருத்து, நீதிமன்றத்தால் தனியாக மதிப்பிட முடியாத தொழில்நுட்ப கேள்வி மீது ஆதாரமாக முன்வைக்கப்படுகிறது. ஒரு நிபுணரின் கருத்தை ஏற்றுக்கொள்ள கட்டாயமில்லாமல், மற்ற ஆதாரங்களுடன் சேர்த்து நீதிமன்றம் அதை எடைபோடுகிறது.',
  'circumstantial-evidence': 'ஒரு உண்மையை நேரடியாக நிரூபிக்காமல், தொடர்புடைய சூழ்நிலைகளின் தொடர்ச்சியிலிருந்து நியாயமான முறையில் நீதிமன்றம் அதை ஊகிக்க அனுமதிக்கும் ஆதாரம். circumstantial evidence மட்டும் கொண்டே நீதிமன்றங்கள் குற்றவாளி என தீர்ப்பளிக்கவோ வழக்கைத் தீர்மானிக்கவோ முடியும், ஆனால் பொதுவாக அனைத்து சூழ்நிலைகளும் சேர்ந்து ஒரே ஒரு விளக்கத்தை முடிவாகக் காட்டும்போது மட்டுமே.',
  'corroboration': 'ஏற்கெனவே அளிக்கப்பட்ட ஒரு ஆதாரத்தை ஆதரித்து உறுதிப்படுத்தும் சுயாதீன ஆதாரம், எடுத்துக்காட்டாக முதல் சாட்சியின் விவரணையை இரண்டாவது சாட்சி உறுதிப்படுத்துவது. சில வகை ஆதாரங்கள், corroboration கிடைக்கும்போது, மேலும் நம்பகமானவையாகக் கருதப்படும் அல்லது சில சூழல்களில் நடைமுறையின்படி தேவைப்படும்.',
  'presumption': 'எதிர் ஆதாரத்தால் மறுக்கப்படாத வரையில், சில உண்மைகளிலிருந்து ஒரு நீதிமன்றம் எடுத்துக்கொள்ள சட்டம் அனுமதிக்கும் அல்லது கட்டாயப்படுத்தும் முடிவு. உதாரணமாக, குறிப்பிட்ட ஆண்டுகளுக்கும் பழையதாகவும் முறையான பாதுகாப்பிலிருந்தும் வந்த ஒரு ஆவணம், தனியாக நிரூபிக்காமலேயே உண்மையானது என presumption ஆக எடுத்துக்கொள்ளப்படலாம்.',
  'interrogatories': 'ஒரு சிவில் வழக்கில் ஒரு தரப்பினர், விசாரணைக்கு முன் வழக்கு தொடர்பான உண்மைகளையோ ஒப்புதல்களையோ பெற, எதிர் தரப்பினரை சத்தியத்தின் பேரில் பதிலளிக்கக் கோரக்கூடிய எழுத்துப்பூர்வ கேள்விகளின் தொகுப்பு.',
  'discovery-of-documents': 'ஒரு சிவில் வழக்கில் ஒரு தரப்பினர், விசாரணை தொடங்குவதற்கு முன், மற்ற தரப்பினரின் வசம் உள்ள, வழக்குக்குத் தொடர்புடைய ஆவணங்களை வெளிப்படுத்தி முன்வைக்குமாறு கோரக்கூடிய நடைமுறை.',
  'evidence-by-affidavit': 'முக்கியமாக தீர்ப்பாயங்கள் மற்றும் ஆணையங்கள் முன் பின்பற்றப்படும் நடைமுறை, இதில் ஒரு சாட்சியின் examination-in-chief நீதிமன்றத்தில் வாய்மொழியாக அளிக்கப்படாமல், சத்தியமிட்ட சத்தியப் பிரமாணப் பத்திரமாகத் தாக்கல் செய்யப்படுகிறது. அந்த சத்தியப் பிரமாணப் பத்திரத்தில் கூறப்பட்டவை மீது cross-examination-க்காக சாட்சியை இன்னும் அழைக்க முடியும்.',
  'primary-evidence': 'நீதிமன்றத்தின் பரிசோதனைக்காக முன்வைக்கப்படும் மூல ஆவணமே, இது அதன் உள்ளடக்கத்தின் நகல் அல்லது வாய்மொழி விவரணை போன்ற secondary evidence-க்கு மாறானது. மூல ஆவணம் கிடைக்கும் இடங்களில், நீதிமன்றங்கள் பொதுவாக primary evidence-ஐ வேண்டுகின்றன.',
  'secondary-evidence': 'மூல ஆவணம் அல்லாத, அதன் உள்ளடக்கத்தைக் காட்டும் ஆதாரம், எடுத்துக்காட்டாக ஒரு சான்றளிக்கப்பட்ட நகல் அல்லது அதைப் பார்த்தவரின் வாய்மொழி விவரணை; மூலம் தொலைந்துவிட்டது அல்லது மற்ற தரப்பினரின் வசம் உள்ளது போன்ற குறிப்பிட்ட சூழல்களில் மட்டுமே இது அனுமதிக்கப்படும்.',
  'leading-question': 'தனது பதிலையே குறிப்புகாட்டும் அல்லது இன்னும் நிரூபிக்கப்படாத ஒரு உண்மையை முன்கூட்டியே ஏற்றுக்கொள்ளும் கேள்வி. அறிமுகம் அல்லது தகராறு இல்லாத விஷயங்களைத் தவிர, examination-in-chief-இன் போது leading questions பொதுவாக அனுமதிக்கப்படுவதில்லை, ஆனால் cross-examination-இன் போது அனுமதிக்கப்படும்.',
  'test-identification-parade': 'பொதுவாக ஒரு மாஜிஸ்திரேட் நடத்தும் நடைமுறை, இதில் ஒரு சாட்சி, குற்றத்தில் சம்பந்தப்பட்ட நபராக சந்தேக நபரை சரியாக அடையாளம் காண முடியுமா என்பதைச் சரிபார்க்க, பல நபர்களின் குழுவிலிருந்து அந்த சந்தேக நபரைக் கண்டறியுமாறு கேட்கப்படுகிறார்.',
  'dying-declaration': 'ஒரு நபர் இறப்பதற்கு முன்பு, தமது மரணத்திற்கான காரணம் அல்லது அதற்கு வழிவகுத்த சூழ்நிலைகள் பற்றிக் கொடுக்கும் அறிக்கை. hearsay-க்கு எதிரான வழக்கமான விதிக்கு விதிவிலக்காக நீதிமன்றங்கள் dying declaration-ஐக் கருதுகின்றன, நம்பகமான ஒரு அறிக்கையின் அடிப்படையிலேயே குற்றம் சாட்டப்பட்டவரைக் குற்றவாளியாகத் தீர்ப்பளிக்கவும் முடியும்.',
  'confession': 'குற்றம் சாட்டப்பட்டவர் ஒரு குற்றத்தில் தமது குற்றத்தை ஒப்புக்கொண்டு அளிக்கும் அறிக்கை; ஒரு சிவில் விவகாரத்தில் தரப்பினர் தமக்கு எதிரான ஒரு உண்மையை ஒப்புக்கொள்ளும் admission-இலிருந்து இது வேறுபட்டது. Indian Evidence Act-க்குப் பதிலாக வந்த ஆதாரச் சட்டமான Bharatiya Sakshya Adhiniyam, 2023 (BSA)-இன் கீழ், மாஜிஸ்திரேட் முன் அல்லாமல் காவல்துறையிடம் மட்டும் அளிக்கப்படும் வாக்குமூலம், பொதுவாக விசாரணையில் குற்றம் சாட்டப்பட்டவருக்கு எதிராகப் பயன்படுத்த முடியாது.',
  'interested-witness': 'ஒரு வழக்கின் முடிவில் ஓரளவு தனிப்பட்ட நாட்டம் உள்ள சாட்சி, எடுத்துக்காட்டாக ஒரு தரப்பினரின் நெருங்கிய உறவினர்; அந்த உறவு காரணமாக மட்டுமே முற்றிலும் நிராகரிக்காமல், அவரது சாட்சியத்தை நீதிமன்றங்கள் மேலும் கவனமாக ஆராய்கின்றன.',
  'proof-of-document': 'நீதிமன்றம் ஒரு ஆவணத்தின் உள்ளடக்கத்தை நம்பும் முன், அது உண்மையானது என்றும், கூறப்பட்டபடியே கையொப்பமிடப்பட்டது அல்லது உருவாக்கப்பட்டது என்றும் பொதுவாக ஒரு சாட்சி மூலமாக நிரூபிக்கும் செயல்முறை. ஒரு ஆவணத்தை நீதிமன்றப் பதிவில் வெறுமனே வைப்பதால் மட்டும் அது நிரூபிக்கப்படுவதில்லை.',
  'chain-of-custody': 'ஒரு ஆயுதம் அல்லது குற்றவியல் மாதிரி போன்ற ஒரு பருப்பொருள் அல்லது மாதிரியைக் கையாண்ட அல்லது அதன் கட்டுப்பாட்டில் இருந்த அனைவரையும் பற்றிய ஆவணப்படுத்தப்பட்ட பதிவு, அது பறிமுதல் செய்யப்பட்ட நேரத்திலிருந்து நீதிமன்றத்தில் முன்வைக்கப்படும் வரை. chain of custody-இல் இடைவெளிகள் அல்லது சரியாக ஆவணப்படுத்தப்படாததால், முன்வைக்கப்பட்ட ஆதாரம் முதலில் பறிமுதல் செய்யப்பட்டதே தானா என்ற சந்தேகம் எழலாம்.',

  // ─── Criminal Procedure ─────────────────────────────────────────
  'first-information-report': 'ஒரு cognizable offence பற்றிய தகவல் காவல்துறைக்கு முதலில் கிடைக்கும்போது அவர்கள் தயாரிக்கும் எழுத்துப்பூர்வ பதிவு, இது ஒரு குற்றவியல் விசாரணையின் முறையான தொடக்கத்தைக் குறிக்கிறது. CrPC-க்குப் பதிலாக வந்த நெறிமுறையான Bharatiya Nagarik Suraksha Sanhita, 2023 (BNSS)-இன் கீழ் இது தாக்கல் செய்யப்படுகிறது.',
  'chargesheet': 'விசாரணையின் முடிவில் காவல்துறை மாஜிஸ்திரேட்டிடம் தாக்கல் செய்யும் அறிக்கை, இதில் சேகரிக்கப்பட்ட ஆதாரங்கள் விவரிக்கப்பட்டு, வழக்கை ஆதரித்தால், விசாரணைக்கு உட்படுத்த வேண்டிய குற்றம் சாட்டப்பட்டவர்களின் பெயர்களும் குறிப்பிடப்படும். CrPC-க்குப் பதிலாக வந்த BNSS-இன் கீழ் இது அதிகாரப்பூர்வமாக காவல் அறிக்கை அல்லது இறுதி அறிக்கை என அழைக்கப்படுகிறது.',
  'bail': 'குற்றஞ்சாட்டப்பட்ட ஒரு நபரை, விசாரணை அல்லது மேலும் நடவடிக்கைகள் நிலுவையில் உள்ளபோது, பொதுவாக பத்திரம் அல்லது பிணை போன்ற நிபந்தனைகளின் அடிப்படையில் காவலிருப்பிலிருந்து விடுவிப்பது. இது விடுதலையோ குற்றமற்றவர் எனத் தீர்மானிப்போ அல்ல; வழக்கு தொடரும்போது காவலிருப்பிலிருந்து மட்டும் விடுவிப்பதே இது.',
  'anticipatory-bail': 'ஒரு நபர் உண்மையில் கைது செய்யப்படுவதற்கு முன்பே, ஒரு குறிப்பிட்ட குற்றச்சாட்டுக்காக அவர் கைது செய்யப்பட்டால் bail-இல் விடுவிக்கப்பட வேண்டும் என முன்கூட்டியே வழங்கப்படும் நீதிமன்ற உத்தரவு. தவறாகவோ நியாயமற்ற முறையிலோ தாம் கைது செய்யப்படக்கூடும் என நம்பும் ஒரு நபரைப் பாதுகாப்பதே இதன் நோக்கம்.',
  'cognizable-offence': 'பொதுவாக மிகவும் கடுமையான ஒரு வகை குற்றம், இதில் காவல்துறை மாஜிஸ்திரேட்டின் முன் அனுமதி இல்லாமலேயே FIR பதிவு செய்து விசாரணை தொடங்கவோ குற்றம் சாட்டப்பட்டவரைக் கைது செய்யவோ முடியும்.',
  'non-cognizable-offence': 'பொதுவாக குறைவான கடுமையான ஒரு வகை குற்றம், இதில் மாஜிஸ்திரேட்டிடமிருந்து முதலில் அனுமதி பெறாமல் காவல்துறை விசாரிக்கவோ குற்றம் சாட்டப்பட்டவரைக் கைது செய்யவோ முடியாது. இத்தகைய வழக்கில் புகார்தாரர் பொதுவாக காவல் நிலையத்தில் வெறுமனே FIR தாக்கல் செய்வதற்குப் பதிலாக, மாஜிஸ்திரேட்டை நேரடியாக அணுக வேண்டும்.',
  'summons': 'ஒரு நபரை ஒரு குறிப்பிட்ட தேதியில் நீதிமன்றத்தில் ஆஜராகுமாறு பணிக்கும் முறையான நீதிமன்ற உத்தரவு, அந்த நபரைக் கைது செய்ய வேண்டிய அவசியமில்லை என நீதிமன்றம் கருதும்போது இது பயன்படுத்தப்படுகிறது. summons-ஐ புறக்கணிப்பது, வாரண்ட் பிறப்பிப்பது உட்பட, விஷயத்தை நீதிமன்றம் தீவிரப்படுத்த வழிவகுக்கும்.',
  'warrant': 'ஒரு நபரைக் கைது செய்து நீதிமன்றத்தில் நிறுத்துமாறு காவல்துறையை பணிக்கும், நீதிமன்றம் பிறப்பிக்கும் எழுத்துப்பூர்வ உத்தரவு. "பிணை பெறத்தக்க" (bailable) வாரண்ட் என்றால், கைது செய்யப்பட்டவுடனேயே அந்த நபர் bail-இல் விடுவிக்கப்படலாம்; "பிணை பெற முடியாத" (non-bailable) வாரண்ட் என்றால், முதலில் அவரை நீதிமன்றத்தில் நிறுத்த வேண்டும்.',
  'remand': 'கைது செய்யப்பட்ட ஒரு நபரை, மேலும் விசாரணைக்காக காவல்துறை காவலுக்கோ அல்லது நீதிமன்ற காவலுக்கோ, விசாரணை அல்லது வழக்கு தொடரும் காலத்திற்கு வரையறுக்கப்பட்ட காலத்திற்கு அனுப்பும் உத்தரவு.',
  'discharge-criminal': 'குற்றம் சாட்டப்பட்டவருக்கு எதிராக நடவடிக்கை தொடர போதிய ஆதாரம் மேலோட்டமாகக் கூட இல்லை என்று கண்டறிந்து, விசாரணைக்கு முன்பே அவரை ஒரு குற்றவியல் வழக்கிலிருந்து நீதிமன்றம் விடுவிக்கும் உத்தரவு. ஆதாரங்கள் மீதான முழு விசாரணைக்குப் பிறகு மட்டுமே வரும் acquittal-இலிருந்து discharge வேறுபட்டது.',
  'acquittal': 'முழு விசாரணைக்குப் பிறகு, குற்றம் சாட்டப்பட்டவர் குற்றம் சுமத்தப்பட்ட குற்றத்தில் குற்றவாளி அல்ல என நீதிமன்றம் அளிக்கும் இறுதி முடிவு. இது அந்தக் குற்றச்சாட்டிலிருந்து குற்றம் சாட்டப்பட்டவரை விடுவிக்கிறது; வரையறுக்கப்பட்ட விதிவிலக்குகளைத் தவிர, அதே குற்றத்திற்காக அவர் மீண்டும் விசாரிக்கப்பட முடியாது.',
  'complainant': 'ஒரு குற்றம் நடந்துள்ளது என்று குற்றஞ்சாட்டி, நீதிமன்றத்திலோ காவல் நிலையத்திலோ குற்றவியல் புகார் கொண்டு வருபவர்; குற்றச்சாட்டு யார் மீது வைக்கப்பட்டுள்ளதோ அந்த accused-இலிருந்து இவர் வேறுபட்டவர்.',
  'accused': 'ஒரு குற்றவியல் குற்றச்சாட்டு யார் மீது வைக்கப்பட்டுள்ளதோ, யார் ஒரு குற்றத்திற்காக விசாரிக்கப்பட்டு, குற்றம் சுமத்தப்பட்டு, அல்லது விசாரணைக்கு உட்படுத்தப்படுகிறாரோ அந்த நபர். நீதிமன்றம் குற்றவாளி என நிரூபிக்கும் வரை accused குற்றமற்றவராகக் கருதப்படுகிறார்.',
  'investigating-officer': 'ஒரு குற்றவியல் வழக்கை விசாரிக்கும் பொறுப்புள்ள காவல் அதிகாரி, இதில் ஆதாரங்களைச் சேகரித்தல், சாட்சிகளின் அறிக்கைகளைப் பதிவு செய்தல், இறுதியில் chargesheet தாக்கல் செய்தல் அல்லது வழக்கை முடித்தல் ஆகியவை அடங்கும்.',
  'cognizance': 'ஒரு புகார், காவல் அறிக்கை, அல்லது மாஜிஸ்திரேட்டின் சொந்தத் தகவலின் அடிப்படையில், ஒரு குற்றத்தை நீதித்துறை ரீதியாகக் கருத்தில் கொண்டு வழக்கைத் தொடர மாஜிஸ்திரேட் எடுக்கும் முறையான நடவடிக்கை. cognizance எடுக்கப்படும் வரை, ஒரு விஷயம் அந்த நீதிமன்றத்தின் முன் முறையான வழக்காக ஆகாது.',
  'framing-of-charge': 'இதுவரை கிடைத்த ஆதாரங்களின் அடிப்படையில், குற்றம் சாட்டப்பட்டவர் செய்ததாகக் கூறப்படும் குறிப்பிட்ட குற்றம் அல்லது குற்றங்களை நீதிமன்றம் முறையாக எழுத்துப்பூர்வமாக விவரிக்கும் கட்டம். இந்த framing of charge-இன் அடிப்படையிலேயே விசாரணை தொடரும், மேலும் அவற்றுக்கு குற்றத்தை ஒப்புக்கொள்கிறாரா மறுக்கிறாரா என குற்றம் சாட்டப்பட்டவரிடம் கேட்கப்படும்.',
  'compounding-of-offence': 'புகார்தாரரும் குற்றம் சாட்டப்பட்டவரும் தங்களுக்குள் சில குற்றவியல் வழக்குகளை, தேவைப்படும் இடங்களில் நீதிமன்றத்தின் அனுமதியுடன், தீர்த்துக்கொண்டு முழு விசாரணையின்றி வழக்கை முடிவுக்குக் கொண்டுவரும் செயல்முறை. சட்டம் குறிப்பாக அனுமதிக்கும் குற்றங்களை மட்டுமே இந்த வகையில் தீர்க்க முடியும்; கடுமையான குற்றங்களை இவ்வாறு பொதுவாகத் தீர்க்க முடியாது.',
  'zero-fir': 'ஒரு cognizable offence-க்காக, குற்றம் நடந்த இடத்தின் மீது உரிய பிராந்திய அதிகார வரம்பு இல்லாத ஒரு காவல் நிலையம் கூட பதிவு செய்யும் FIR. பின்னர் இது விசாரணைக்காக உரிய அதிகார வரம்புள்ள காவல் நிலையத்திற்கு மாற்றப்படும்.',
  'quashing-of-fir': 'உயர் நீதிமன்றத்தின் உள்ளார்ந்த அதிகாரங்களை நாடி, ஒரு FIR அல்லது நடைமுறையிலுள்ள குற்றவியல் நடவடிக்கைகளை ரத்து செய்யுமாறு கோரி தாக்கல் செய்யப்படும் மனு; இவை அடிப்படையற்றவை, சட்ட நடைமுறையை தவறாகப் பயன்படுத்துவது, அல்லது தரப்பினருக்கிடையே தகராறு ஏற்கெனவே உண்மையாகத் தீர்க்கப்பட்டுவிட்டது என்பதே பொதுவான காரணங்களாகக் கூறப்படும்.',
  'plea-bargaining': 'Bharatiya Nagarik Suraksha Sanhita, 2023 (BNSS)-இன் கீழ் உள்ள செயல்முறை, இதில் குற்றம் சாட்டப்பட்டவர், குற்றத்தை ஒப்புக்கொள்வதற்குப் பதிலாக குறைந்த தண்டனை பேச்சுவார்த்தை நடத்த விண்ணப்பிக்கலாம்; இது குறிப்பிட்ட வகை குற்றங்களுக்கு மட்டுமே கிடைக்கும்.',
  'default-bail': 'Bharatiya Nagarik Suraksha Sanhita, 2023 (BNSS)-இன் கீழ் அனுமதிக்கப்பட்ட காலத்திற்குள் காவல்துறை விசாரணையை முடித்து chargesheet தாக்கல் செய்யத் தவறினால், குற்றச்சாட்டு எவ்வளவு கடுமையானதாக இருந்தாலும் குற்றம் சாட்டப்பட்டவருக்கு உரிமையாகக் கிடைக்கும் bail.',
  'bail-bond': 'bail-இல் விடுவிக்கப்படும்போது குற்றம் சாட்டப்பட்டவர் கையொப்பமிடும் ஆவணம், தேவைப்படும்போது நீதிமன்றத்தில் ஆஜராவதாக உறுதிமொழி அளிக்கிறது; பெரும்பாலும் ஒன்று அல்லது அதற்கு மேற்பட்ட பிணையாளர்களும் இதில் இடம்பெறுவர், அவர்கள் குற்றம் சாட்டப்பட்டவரை ஆஜர்படுத்துவதாகவோ அல்லது ஆஜராகத் தவறினால் குறிப்பிட்ட தொகையை இழப்பதாகவோ உறுதிமொழி அளிப்பர்.',
  'private-complaint': 'காவல்துறை மூலமாக அல்லாமல், ஒரு தனிநபர் மாஜிஸ்திரேட்டிடம் நேரடியாகத் தாக்கல் செய்யும் குற்றவியல் புகார்; non-cognizable offence-களுக்கோ, அல்லது ஒரு cognizable offence-க்கு FIR பதிவு செய்ய காவல்துறை மறுத்த நிலையிலோ இது பொதுவாகப் பயன்படுத்தப்படுகிறது.',
  'proclaimed-offender': 'கைது தவிர்க்க தப்பி ஓடியிருப்பதாகவோ மறைந்திருப்பதாகவோ நீதிமன்றம் முறையாக அறிவிக்கும் நபர்; இதற்குப் பிறகு, அவர் ஆஜராகும் வரை, சொத்தை இணைத்துக்கொள்வது உட்பட, அவருக்கு எதிராக மேலும் நடவடிக்கைகள் எடுக்க நீதிமன்றம் முடியும்.',
  'conviction': 'விசாரணைக்குப் பிறகு, குற்றம் சாட்டப்பட்டவர் குற்றம் சுமத்தப்பட்ட குற்றத்தில் குற்றவாளி என நீதிமன்றம் அளிக்கும் இறுதி முடிவு, இது நீதிமன்றம் தண்டனை வழங்குவதற்கு வழிவகுக்கிறது. இது acquittal-க்கு நேர்மாறான முடிவு.',
  'sentence': 'ஒரு நபரை குற்றத்தில் conviction செய்த பிறகு நீதிமன்றம் அவருக்கு வழங்கும் சிறை தண்டனை அல்லது அபராதம் போன்ற தண்டனை. பொருத்தமான தண்டனை பற்றி தீர்ப்பு வழங்குவதற்கு முன் நீதிமன்றங்கள் பொதுவாக குற்றவாளியை தனியாக விசாரிக்கும்.',
  'probation': 'சிறை தண்டனையை அனுபவிக்க அனுப்புவதற்குப் பதிலாக, நீதிமன்றம் நிர்ணயிக்கும் கண்காணிப்பு மற்றும் நிபந்தனைகளின் அடிப்படையில், நல்லொழுக்கத்தின் பேரில் தண்டனை பெற்றவரை விடுவிக்கும் உத்தரவு. பொதுவாக முதல் முறை குற்றம் செய்தவர்களுக்கோ குறைவான கடுமையான குற்றங்களுக்கோ இது வழங்கப்படும்.',
  'status-report': 'நீதிமன்றத்தின் உத்தரவுப்படி, ஒரு வழக்கை விசாரிப்பதில் ஏற்பட்டுள்ள முன்னேற்றத்தைத் தெரிவிக்க காவல்துறை நீதிமன்றத்தில் தாக்கல் செய்யும் அறிக்கை.',
  'closure-report': 'பெயரிடப்பட்ட சந்தேக நபர்களுக்கு எதிராக வழக்கு எதுவும் இல்லை என்றும், விஷயம் விசாரணைக்குத் தொடரக்கூடாது என்றும் கூறி, விசாரணையின் முடிவில் காவல்துறை தாக்கல் செய்யும் அறிக்கை. CrPC-க்குப் பதிலாக வந்த நெறிமுறையான Bharatiya Nagarik Suraksha Sanhita, 2023 (BNSS)-இன் கீழ் இது தாக்கல் செய்யப்படுகிறது, மேலும் மாஜிஸ்திரேட் இதை ஏற்றுக்கொள்வதற்கு முன் புகார்தாரருக்கு விசாரிக்கப்பட உரிமை உண்டு.',
  'protest-petition': 'ஒரு closure report-ஐ எதிர்த்து, அதை ஏற்றுக்கொள்ளாமல், அதற்குப் பதிலாக குற்றத்தை cognizance எடுத்து வழக்கைத் தொடருமாறு கோரி, புகார்தாரர் மாஜிஸ்திரேட்டிடம் தாக்கல் செய்யும் எதிர்ப்பு மனு.',

  // ─── Civil Remedies ───────────────────────────────────────────────
  'temporary-injunction': 'முதன்மை வழக்கு இன்னும் தீர்க்கப்படாதிருக்கும்போது, தகராறான சொத்தை விற்பது போன்ற ஒரு குறிப்பிட்ட செயலை தரப்பினர் செய்வதைத் தற்காலிகமாகத் தடுக்கும் நீதிமன்ற உத்தரவு. இடைப்பட்ட காலத்தில் எடுக்கப்படும் நடவடிக்கைகளால் இறுதி முடிவு பொருளற்றதாகிவிடாமல், நிலைமையை அப்படியே பாதுகாப்பதே இதன் நோக்கம்.',
  'permanent-injunction': 'வழக்கின் முடிவில் வழங்கப்படும் இறுதி நீதிமன்ற உத்தரவு, ஒரு குறிப்பிட்ட செயலைச் செய்வதிலிருந்து தரப்பினரை நிரந்தரமாகத் தடுக்கிறது. temporary injunction போலல்லாமல், இது ஒரு தற்காலிக நடவடிக்கை அல்ல, மாறாக வழக்கின் மீதான நீதிமன்றத்தின் இறுதி முடிவின் ஒரு பகுதியாகும்.',
  'specific-performance': 'ஒப்பந்தத்தை மீறியதற்கு வெறுமனே இழப்பீடு செலுத்துவதற்குப் பதிலாக, ஒரு குறிப்பிட்ட சொத்தின் விற்பனையை முடிப்பது போன்ற, ஒப்பந்தத்தின் கீழ் உள்ள கடமைகளை தரப்பினர் உண்மையில் நிறைவேற்றுமாறு பணிக்கும் நீதிமன்ற உத்தரவு. பணம் மட்டும் மீறலுக்குப் போதுமான ஈடாக இருக்காத சூழல்களில் முக்கியமாக நீதிமன்றங்கள் இந்த நிவாரணத்தை வழங்குகின்றன.',
  'damages': 'ஒப்பந்த மீறல் அல்லது தீங்கு (tort) போன்ற ஒரு தவறால் ஏற்பட்ட இழப்பு அல்லது சேதத்திற்கு இழப்பீடாக, ஒரு தரப்பினர் மற்றொரு தரப்பினருக்குச் செலுத்த வேண்டும் என நீதிமன்றம் உத்தரவிடும் பணத் தொகை. பணத்தால் முடிந்த அளவுக்கு, தவறு நடக்காதிருந்தால் பாதிக்கப்பட்ட தரப்பினர் இருந்திருக்கும் நிலைக்கு அவரை கொண்டு வருவதே இந்தத் தொகையின் நோக்கம்.',
  'preliminary-decree': 'ஒரு விஷயத்தில் தரப்பினரின் உரிமைகளைத் தீர்மானிக்கும் ஆனால் கணக்கெடுத்தல் அல்லது சொத்தைப் பிரித்தல் போன்ற சில மேலதிக படிகளை, வழக்கை முழுமையாக மூடுவதற்கு முன் தீர்க்க விடுக்கும் decree. மீதமுள்ள படிகள் முடிந்ததும் final decree அதைத் தொடரும்.',
  'final-decree': 'சொத்தின் துல்லியமான பிரிவு போன்ற மீதமுள்ள அனைத்துக் கேள்விகளும் தீர்க்கப்பட்ட பிறகு, நேரடியாகவோ அல்லது preliminary decree-க்குப் பிறகோ வழங்கப்படும், ஒரு வழக்கை முழுமையாக முடித்துவைக்கும் decree.',
  'execution-of-decree': 'வழக்கில் வென்ற தரப்பினர், தோற்ற தரப்பினரின் சொத்தைப் பறிமுதல் செய்வது அல்லது நிலுவைத் தொகையை மீட்பது போன்ற வழிகளில், நீதிமன்றத்தின் decree-ஐ உண்மையில் அமல்படுத்தும் சட்ட நடைமுறை. வழக்கில் வெற்றி பெறுவது தானாகவே நிவாரணம் கைக்குக் கிடைக்கும் என்று பொருள்படாது; நடைமுறையில் அதைச் சாதிக்க execution நடவடிக்கைகள் பெரும்பாலும் தேவைப்படும்.',
  'review-civil': 'ஒரு தீர்ப்பு அல்லது உத்தரவு வழங்கிய அதே நீதிமன்றத்திடம், பதிவில் தெரியும் தெளிவான உண்மை அல்லது சட்டப் பிழை, அல்லது புதிதாகக் கண்டறியப்பட்ட ஆதாரம் காரணமாக, அதன் சொந்த முடிவை மீண்டும் பரிசீலிக்குமாறு கோரும் வேண்டுகோள். மேல் நீதிமன்றம் விசாரிக்கும் appeal-ஐ விடவும், கீழமை நீதிமன்றம் தனது அதிகார வரம்பிற்குள் செயல்பட்டதா என்பதை ஆராயும் revision-ஐ விடவும் இதன் வரம்பு குறுகியது.',
  'revision-civil': 'ஒரு வழக்கில் உண்மைகள் மீதான கீழமை நீதிமன்றத்தின் முடிவுகளின் சரியான தன்மையை மீண்டும் ஆராய்வதற்குப் பதிலாக, அது தனது அதிகார வரம்பிற்குள் செயல்பட்டதா, முறையான நடைமுறையைப் பின்பற்றியதா என்பதை ஆராயுமாறு மேல் நீதிமன்றத்திடம் செய்யப்படும் விண்ணப்பம். முடிவின் தகுதி குறித்தே ஆராயக்கூடிய appeal-ஐ விட revision-இன் வரம்பு மிகவும் குறுகியது.',
  'appeal': 'கீழமை நீதிமன்றத்தின் முடிவை, அதன் உண்மை மற்றும் சட்டம் சார்ந்த கண்டறிதல்கள் உட்பட, தகுதியின் அடிப்படையில் மீள்பரிசீலனை செய்து மாற்றுமாறு மேல் நீதிமன்றத்திடம் செய்யப்படும் கோரிக்கை. கீழமை நீதிமன்றம் அதன் அதிகார வரம்பிற்குள் இருந்து முறையான நடைமுறையைப் பின்பற்றியதா என்பதை மட்டும் முதன்மையாக சரிபார்க்கும் revision-ஐ விடவும், தெளிவான பிழைக்காக அதே நீதிமன்றம் தனது முடிவை மீண்டும் பரிசீலிக்குமாறு கோரும் review-ஐ விடவும் இதன் வரம்பு பரந்தது.',
  'suit-for-recovery': 'செலுத்தப்படாத கடன், ஒப்பந்தத்தின் கீழ் செலுத்தப்படாத நிலுவைத் தொகை, அல்லது விற்கப்பட்ட பொருட்களின் விலை போன்ற, ஒரு நபர் மற்றொருவருக்குக் கொடுக்க வேண்டிய பணத்தொகையை மீட்க தாக்கல் செய்யப்படும் சிவில் வழக்கு.',
  'declaratory-suit': 'ஒரு நபர், ஒரு சொத்தின் மீதான தனது உரிமம் போன்ற, தமது சட்ட உரிமையையோ அந்தஸ்தையோ முறையாக அறிவிக்குமாறு நீதிமன்றத்தைக் கோரும் சிவில் வழக்கு; உடைமையை மீட்பது போன்ற மேலதிக நிவாரணத்தை நீதிமன்றம் கூடுதலாக உத்தரவிட வேண்டும் என்று கோராமல், இது மட்டுமே கோரப்படும்.',
  'partition-suit': 'ஒரு சொத்தின் இணை உரிமையாளர், பெரும்பாலும் குடும்ப உறுப்பினர்களுக்குள், சொத்தைப் பிரித்து ஒவ்வொரு உரிமையாளரின் தனித்தனி பங்கையும் குறியிடுமாறு நீதிமன்றத்தைக் கோரி தாக்கல் செய்யும் சிவில் வழக்கு.',
  'restitution': 'மேல்முறையீட்டில் பின்னர் மாற்றப்பட்ட அல்லது மறுக்கப்பட்ட ஒரு decree அல்லது உத்தரவுக்கு முன் தரப்பினர் இருந்த நிலைக்கு அவரை மீண்டும் கொண்டுவரும் உத்தரவு, பொதுவாக அதன்கீழ் பெறப்பட்ட பணத்தையோ சொத்தையோ திரும்ப அளிக்குமாறு மற்ற தரப்பினரைப் பணிப்பதன் மூலம்.',
  'set-off-and-counterclaim': 'வாதி தமக்குக் கொடுக்க வேண்டிய ஒரு தனி கடனைச் சுட்டிக்காட்டி, வாதிக்குத் தாம் கொடுக்க வேண்டியதைக் குறைக்கவோ முற்றிலும் ரத்து செய்யவோ ஒரு set-off பிரதிவாதிக்கு வழிவகுக்கிறது. ஒரு counterclaim இன்னும் மேலே சென்று, தனியான வழக்கு தாக்கல் செய்வதற்குப் பதிலாக, அதே வழக்குக்குள்ளேயே வாதிக்கு எதிராக தனது சொந்த சுயாதீன கோரிக்கையை பிரதிவாதி முன்வைக்க அனுமதிக்கிறது.',
  'mesne-profits': 'வேறொருவரின் சொத்தை முறையற்று ஆக்கிரமித்து பயன்படுத்தியதற்கு, அந்தத் தவறான உடைமைக் காலத்தில் நபர் பெற்ற ஆதாயம் அல்லது உண்மையான உரிமையாளர் இழந்த ஆதாயத்தின் அடிப்படையில் கணக்கிடப்பட்டு, அந்த நபர் செலுத்த வேண்டும் என நீதிமன்றம் உத்தரவிடக்கூடிய இழப்பீடு.',
  'rejection-of-plaint': 'cause of action வெளிப்படாதது அல்லது போதுமான முத்திரைத் தாள் இல்லாதது போன்ற அடிப்படைக் குறைபாடு plaint-இலேயே இருப்பதால், முழு தகுதி விசாரணைக்குச் செல்லாமலேயே, வழக்கைத் தொடராமல் நீதிமன்றம் மறுக்கும் உத்தரவு. விசாரணைக்குப் பிறகான தள்ளுபடிக்கு மாறாக, சில சூழல்களில், அதே cause of action-இன் அடிப்படையில் புதிய வழக்கு தாக்கல் செய்ய வாதிக்கு இது வாய்ப்பளிக்கிறது.',
  'return-of-plaint': 'வழக்கை விசாரிக்க தனக்கு அதிகார வரம்பு இல்லை என நீதிமன்றம் கண்டறியும்போது, சரியான நீதிமன்றத்தில் முன்வைக்க plaint-ஐ வாதிக்குத் திருப்பி அளிக்கும் உத்தரவு. இதன் பிறகு வாதி அதே plaint-ஐ உரிய நீதிமன்றத்தில் மீண்டும் தாக்கல் செய்யலாம்.',
  'mandatory-injunction': 'வெறுமனே ஒரு செயலைச் செய்யாமல் தடுப்பதற்குப் பதிலாக, ஆக்கிரமிப்பை அகற்றுதல் அல்லது இடிக்கப்பட்ட கட்டமைப்பை மீட்டமைத்தல் போன்ற ஒரு குறிப்பிட்ட செயலை சுறுசுறுப்பாகச் செய்யுமாறு தரப்பினரைப் பணிக்கும் நீதிமன்ற உத்தரவு. தரப்பினரை செயல்படுவதிலிருந்து தடுப்பதை மட்டுமே செய்யும் prohibitory injunction-இலிருந்து இது வேறுபட்டது.',
  'interpleader-suit': 'இருவரோ அதற்கு மேற்பட்ட நபர்களோ கோரிக்கை வைக்கும் பணத்தையோ சொத்தையோ வைத்திருக்கும், அவர்களில் எவரையும் எதிர்த்து வாதிடுவதில் தனிப்பட்ட நாட்டமில்லாத நபர், போட்டி கோரிக்கையாளர்களில் யார் உண்மையில் அதற்கு உரிமையுடையவர் என்பதை நீதிமன்றம் தீர்மானிக்குமாறு கோரி தாக்கல் செய்யும் வழக்கு.',
  'garnishee-order': 'judgment-debtor-க்குப் பணம் கொடுக்க வேண்டிய, அல்லது அவருக்குச் சொந்தமான பணத்தை வைத்திருக்கும் ஒரு வங்கி போன்ற மூன்றாம் தரப்பினரை, அந்தத் தொகையை judgment-debtor-க்குப் பதிலாக decree-holder-க்கு நேரடியாகச் செலுத்துமாறு பணிக்கும், execution நடவடிக்கைகளில் வழங்கப்படும் உத்தரவு.',
  'attachment-before-judgment': 'தமக்கு எதிராக இறுதியில் வரக்கூடிய decree-ஐ முறியடிக்க, பிரதிவாதி தனது சொத்துகளை அப்புறப்படுத்தவோ அகற்றவோ வாய்ப்புள்ளது என நீதிமன்றம் திருப்தியடைந்தால், வழக்கு இன்னும் நிலுவையில் இருக்கும்போதே பிரதிவாதியின் சொத்தை இணைக்கும் உத்தரவு.',
  'costs': 'நீதிமன்றக் கட்டணம் மற்றும் சட்டச் செலவுகள் போன்ற வழக்காடும் செலவுகள், இவற்றை ஒரு தரப்பினர் மற்றொருவருக்குச் செலுத்துமாறு, பொதுவாக தோற்ற தரப்பினர் வென்ற தரப்பினருக்குச் செலுத்துமாறு, வழக்கின் மீதான தனது இறுதி முடிவின் ஒரு பகுதியாக நீதிமன்றம் பணிக்கலாம்.',
  'decree-holder-and-judgment-debtor': 'decree-holder என்பவர், நீதிமன்றம் தமக்கு சாதகமாக decree வழங்கியுள்ள, அதை அமல்படுத்த உரிமையுள்ள தரப்பினர். judgment-debtor என்பவர், decree தமக்கு எதிராக வழங்கப்பட்டு, பொதுவாக பணம் செலுத்த வேண்டிய அல்லது சொத்தை ஒப்படைக்க வேண்டிய கடப்பாட்டைச் சுமக்கும் தரப்பினர்.',
  'consent-decree': 'தகுதி மீதான போராடிய விசாரணைக்குப் பிறகு அல்லாமல், வழக்கின் இரு தரப்பினரும் தாமாகவே ஒப்புக்கொண்ட ஒரு சமரசத்தின் விதிமுறைகளின்படி நீதிமன்றம் வழங்கும் decree. ஒருமுறை வழங்கப்பட்டதும், வரையறுக்கப்பட்ட சூழல்களைத் தவிர, அடிப்படை முடிவு தவறானது என்ற காரணத்தில் இதை appeal-இல் பொதுவாக எதிர்த்து வாதிட முடியாது.',
  'abatement-of-suit': 'ஒரு வழக்கு, அல்லது அதில் ஒரு குறிப்பிட்ட தரப்பினர் தொடர்பான பகுதி, தானாகவே முடிவுக்கு வருவது; பெரும்பாலும் ஒரு தரப்பினர் இறந்துவிட்டு, சட்டம் அனுமதிக்கும் காலத்திற்குள் அவரது சட்ட வாரிசுகள் பதிவில் கொண்டுவரப்படாததே இதற்குக் காரணம்.',
  'liquidated-damages': 'ஒரு ஒப்பந்தத்தின் தரப்பினர், அதில் ஒருவர் மீறினால் இழப்பீடாகச் செலுத்தப்பட வேண்டும் என முன்கூட்டியே ஒப்புக்கொள்ளும் ஒரு குறிப்பிட்ட பணத்தொகை; மீறல் நடந்த பிறகு நீதிமன்றம் மதிப்பிட்டு நிர்ணயிக்க வேண்டிய unliquidated damages-இலிருந்து இது வேறுபட்டது.',
  'receiver': 'வழக்கு தீர்க்கப்படும்போது, தகராறுக்கு உள்ளான சொத்து வீணாகாமலோ சேதமடையாமலோ தவறாக கையாளப்படாமலோ இருக்க, அதை தற்காலிகமாக பொறுப்பேற்று, நிர்வகிக்க, அல்லது பாதுகாக்க நீதிமன்றம் நியமிக்கும் நபர்.',

  // ─── Tribunals & Forums ───────────────────────────────────────────
  'original-application': 'கடன் வாங்கியவரிடமிருந்து நிலுவைத் தொகையை மீட்க, ஒரு வங்கி அல்லது நிதி நிறுவனம் Debt Recovery Tribunal (DRT) முன் தாக்கல் செய்யும் முதன்மை வழக்கு ஆவணம்; சிவில் நீதிமன்றத்தில் plaint செய்யும் பணிக்கு இது ஒப்பானது.',
  'securitisation-application': 'SARFAESI Act-இன் கீழ் பிணையச் சொத்தைக் கையகப்படுத்த அல்லது விற்க கடன் வழங்குநர் எடுத்த நடவடிக்கைகளை எதிர்த்து, கடன் வாங்கியவரோ பாதிக்கப்பட்ட மற்றொரு நபரோ DRT முன் தாக்கல் செய்யும் விண்ணப்பம்.',
  'sarfaesi': 'Securitisation and Reconstruction of Financial Assets and Enforcement of Security Interest Act, 2002 என்பதன் சுருக்கம். கடன் வாங்கியவர் தவறினால், வங்கிகளும் சில நிதி நிறுவனங்களும், முதலில் நீதிமன்றத்தில் வழக்குத் தொடராமலே, கடனுக்குப் பிணையமாக வைக்கப்பட்ட சொத்தை நேரடியாகக் கையகப்படுத்தி விற்க இது அனுமதிக்கிறது.',
  'recovery-certificate': 'கடன் வழங்குநருக்குச் சாதகமாக ஒரு Original Application-ஐ தீர்மானித்த பிறகு, DRT வழங்கும் சான்றிதழ், கடன் வாங்கியவரிடமிருந்து, அவரது சொத்தை இணைத்து விற்பது உட்பட, நிலுவைத் தொகையை மீட்க அங்கீகரிக்கிறது.',
  'debt-recovery-officer': 'ஒரு Recovery Certificate வழங்கப்பட்டதும், கடன் வாங்கியவரின் சொத்தை இணைத்து ஏலம் விடுவது போன்ற மீட்பு நடவடிக்கையை உண்மையில் நிறைவேற்றும் பொறுப்புள்ள, DRT-இல் இணைந்த அதிகாரி.',
  'cirp': 'Insolvency and Bankruptcy Code-இன் கீழ் நடத்தப்படும் செயல்முறை, இதில் கடன்களைத் தவறிய ஒரு நிறுவனத்தை நியமிக்கப்பட்ட resolution professional பொறுப்பேற்று, ஒரு resolution plan-இன் கீழ் அதை புத்துயிர்ப்பிக்கவோ அல்லது liquidation நோக்கி நகர்த்தவோ அதன் கடன் வழங்குநர்களுடன் இணைந்து செயல்படுவார்.',
  'miscellaneous-application': 'முற்றிலும் புதிய கோரிக்கையை முன்வைக்காமல், நடைமுறை ரீதியான தெளிவுபடுத்தல் கோருவது போன்ற, நிலுவையிலுள்ள வழக்கு தொடர்பான ஒரு குறிப்பிட்ட வழிகாட்டுதலையோ நிவாரணத்தையோ கோரி NCLT அல்லது NCLAT முன் தாக்கல் செய்யப்படும் விண்ணப்பம்.',
  'resolution-plan': 'CIRP நடைபெறும்போது, ஒரு வருங்கால வாங்குநரோ முதலீட்டாளரோ முன்வைக்கும் திட்டம், நிதி நெருக்கடியில் உள்ள நிறுவனத்தை எவ்வாறு புத்துயிர்ப்பிப்பது, அதன் கடன் வழங்குநர்களுக்கு எவ்வாறு பணம் செலுத்துவது என்பதை முன்மொழிகிறது. இது செயல்படுவதற்கு முன் Committee of Creditors-ஆலும் பின்னர் NCLT-ஆலும் அங்கீகரிக்கப்பட்டிருக்க வேண்டும்.',
  'committee-of-creditors': 'CIRP நடைபெறும்போது உருவாக்கப்படும், முதன்மையாக நிறுவனத்தின் financial creditor-களைக் கொண்ட அமைப்பு; எந்த resolution plan-ஐ அங்கீகரிப்பது அல்லது நிறுவனத்தை liquidation செய்ய வேண்டுமா என்பது போன்ற முக்கிய விஷயங்களை இது தீர்மானிக்கும்.',
  'operational-creditor': 'வழங்கப்பட்ட பொருட்கள் அல்லது செய்யப்பட்ட சேவைகளுக்காக ஒரு நிறுவனம் பணம் செலுத்த வேண்டிய கடன் வழங்குநர், எடுத்துக்காட்டாக ஒரு விற்பனையாளர் அல்லது சப்ளையர்; கடனாகவோ முன்பணமாகவோ கொடுக்கப்பட்ட தொகைக்காக நிறுவனம் பணம் செலுத்த வேண்டிய financial creditor-இலிருந்து இவர் வேறுபட்டவர்.',
  'financial-creditor': 'வங்கிக் கடன் அல்லது debenture போன்ற, கடனாகக் கொடுக்கப்பட்ட பணத்திலிருந்தோ ஒத்த நிதி ஏற்பாட்டிலிருந்தோ எழும் கடனை ஒரு நிறுவனம் செலுத்த வேண்டிய கடன் வழங்குநர்; பொருட்கள் அல்லது சேவைகளுக்காகப் பணம் பெற வேண்டிய operational creditor-இலிருந்து இவர் வேறுபட்டவர்.',
  'consumer-complaint': 'ஒரு விற்பனையாளர் அல்லது சேவை வழங்குநரால் ஏற்பட்ட deficiency in service, பொருட்களில் குறைபாடு, அல்லது unfair trade practice குறித்து குற்றஞ்சாட்டி, இழப்பீடு அல்லது வேறு நிவாரணம் கோரி, ஒரு நுகர்வோர் Consumer Commission முன் தாக்கல் செய்யும் ஆவணம்.',
  'opposite-party': 'ஒரு நுகர்வோர் Consumer Commission முன் புகார் தாக்கல் செய்யும் விற்பனையாளர், உற்பத்தியாளர், அல்லது சேவை வழங்குநர்; ஒரு வழக்கமான சிவில் வழக்கில் பிரதிவாதிக்கு இவர் ஒப்பானவர்.',
  'deficiency-in-service': 'வாக்குறுதி அளிக்கப்பட்டதற்கோ சட்டம் தேவைப்படுத்துவதற்கோ ஒப்பிடுகையில், ஒரு சேவையின் தரத்திலோ தன்மையிலோ வழங்கும் விதத்திலோ உள்ள குறைபாடு அல்லது போதாமை. ஒரு நுகர்வோர் Consumer Commission முன் புகார் தாக்கல் செய்யக் கூடிய முதன்மைக் காரணங்களில் இதுவும் ஒன்று.',
  'unfair-trade-practice': 'பொருட்கள் அல்லது சேவைகளை விளம்பரப்படுத்த அல்லது விற்க ஒரு விற்பனையாளரோ சேவை வழங்குநரோ பயன்படுத்தும் தவறுக்கு வழிவகுக்கும் அல்லது ஏமாற்றும் முறை, எடுத்துக்காட்டாக பொய் விளம்பரம் அல்லது ஒரு பொருளின் தரத்தைத் தவறாகக் குறிப்பிடுதல். மேலும் ஒரு குறிப்பிட்ட இழப்பை அனுபவித்ததைக் காட்ட வேண்டிய அவசியமில்லாமலேயே, ஒரு நுகர்வோர் இது குறித்து Consumer Commission முன் புகார் கொடுக்கலாம்.',
  'consumer-commission-hierarchy': 'நுகர்வோர் புகார்களை விசாரிக்கும் Consumer Commission-களின் மூன்றடுக்கு அமைப்பு, கோரிக்கையின் மதிப்பின் அடிப்படையில் ஒழுங்கமைக்கப்பட்டுள்ளது. District Commission ₹50 லட்சம் வரையிலான கோரிக்கைகளையும், State Commission ₹50 லட்சத்திற்கும் ₹2 கோடிக்கும் இடைப்பட்ட கோரிக்கைகளையும் District Commission-இலிருந்து வரும் மேல்முறையீடுகளையும், National Commission ₹2 கோடிக்கு மேலான கோரிக்கைகளையும் State Commission-இலிருந்து வரும் மேல்முறையீடுகளையும் கையாளும்.',
  'special-leave-petition': 'அரசியலமைப்பின் Article 136-இன் கீழ், நாட்டின் எந்த நீதிமன்றம் அல்லது தீர்ப்பாயத்தின் தீர்ப்பு அல்லது உத்தரவுக்கு எதிராக மேல்முறையீடு செய்ய சிறப்பு அனுமதி கோரி உச்ச நீதிமன்றத்தில் தாக்கல் செய்யப்படும் மனு. உச்ச நீதிமன்றத்தின் விருப்புரிமை அனுமதி முதலில் தேவைப்படுவதால், பொதுவாக உரிமையாக இருக்கும் சாதாரண appeal-இலிருந்து இது ஒரு தனி படியாகும்.',
  'debts-recovery-appellate-tribunal': 'Original Application அல்லது Securitisation Application போன்றவற்றில் DRT வழங்கிய உத்தரவுகளுக்கு எதிரான மேல்முறையீடுகளை விசாரிக்கும் மேல்முறையீட்டுத் தீர்ப்பாயம்.',
  'pre-deposit': 'பெரும்பாலும் DRT, NCLT, அல்லது SARFAESI உத்தரவுக்கு எதிரான மேல்முறையீடு பதிவு செய்யப்பட்டு விசாரிக்கப்படுவதற்கு முன், மேல்முறையீட்டுத் தீர்ப்பாயத்தில் தரப்பினர் செலுத்த வேண்டிய பணத்தொகை, பொதுவாக தகராறில் உள்ள தொகையின் சதவீதமாக நிர்ணயிக்கப்படும்.',
  'national-company-law-tribunal': 'நிறுவனத் தகராறுகள், இணைப்புகள், மற்றும் CIRP உட்பட, நிறுவனச் சட்டம் மற்றும் insolvency தொடர்பான விஷயங்களைத் தீர்மானிக்கும் சிறப்புத் தீர்ப்பாயம்.',
  'national-company-law-appellate-tribunal': 'National Company Law Tribunal வழங்கும் உத்தரவுகளுக்கு எதிரான மேல்முறையீடுகளை விசாரிக்கும் மேல்முறையீட்டுத் தீர்ப்பாயம்.',
  'corporate-debtor': 'கடன்களைத் தவறியதால், அதற்கு எதிராக CIRP தொடங்கப்பட்டுள்ள நிறுவனம்.',
  'resolution-professional': 'CIRP நடைபெறும்போது நிறுவனத்தின் விவகாரங்களை நடத்த நியமிக்கப்படும் insolvency நிபுணர், இதில் கடன் வழங்குநர்களின் கோரிக்கைகளை அழைத்து சரிபார்ப்பதும், resolution plan தயாரிப்பதை மேற்பார்வை செய்வதும் அடங்கும். செயல்முறையின் ஆரம்ப கட்டத்தில், இந்தப் பொறுப்பு இடைக்கால அடிப்படையில் வைத்திருக்கப்படும்.',
  'moratorium-ibc': 'ஒரு நிறுவனத்திற்கு எதிராக CIRP ஏற்றுக்கொள்ளப்பட்டதும் நடைமுறைக்கு வரும், மீட்பு வழக்குகள் மற்றும் பிணையத்தை அமல்படுத்துதல் உட்பட, அதற்கு எதிரான பெரும்பாலான சட்ட நடவடிக்கைகளைத் தாக்கல் செய்வதையோ தொடர்வதையோ தானாக நிறுத்தி வைக்கும் முடக்கம். செயல்முறை நடைபெறும் வரை இது நீடிக்கும்.',
  'liquidator': 'CIRP ஒரு அங்கீகரிக்கப்பட்ட resolution plan-ஐ விளைவிக்காததால் நிறுவனம் liquidation-க்கு உத்தரவிடப்பட்டதும், அதன் சொத்துகளை விற்று வருமானத்தை கடன் வழங்குநர்களுக்கு விநியோகிக்க நியமிக்கப்படும் insolvency நிபுணர்.',
  'possession-notice-sarfaesi': 'கடன் வாங்கியவர் தவறியபிறகு, SARFAESI Act-இன் கீழ் வங்கியோ நிதி நிறுவனமோ வழங்கும் அறிவிப்பு, கடனுக்குப் பிணையமாக வைக்கப்பட்ட சொத்தை கடன் வழங்குநர் கையகப்படுத்திவிட்டதாகத் தெரிவிக்கிறது.',
  'division-bench': 'இரண்டு அல்லது அதற்கு மேற்பட்ட நீதிபதிகள் இணைந்து அமரும் உயர் நீதிமன்றம் அல்லது உச்ச நீதிமன்ற அமர்வு; ஒரு நீதிபதி மட்டும் அமரும் Single Judge Bench-இலிருந்து இது வேறுபட்டது. ஒரு Single Judge-இன் உத்தரவுக்கு எதிரான மேல்முறையீடுகள் போன்ற சில விஷயங்களை Division Bench மட்டுமே விசாரிக்க வேண்டும்.',
  'adjudicating-authority': 'CIRP தொடங்குவதற்கான விண்ணப்பத்தை ஏற்றுக்கொள்வது அல்லது நிராகரிப்பது போன்ற, Insolvency and Bankruptcy Code-இன் கீழ் உள்ள விஷயங்களைத் தீர்மானிக்கும்போது National Company Law Tribunal ஏற்கும் பங்கு.',

  // ─── Company Law ──────────────────────────────────────────────────
  'board-resolution': 'வங்கிக் கணக்கு திறப்பது, ஒரு அதிகாரியை நியமிப்பது, அல்லது ஒரு பரிவர்த்தனையை அங்கீகரிப்பது போன்ற ஒரு குறிப்பிட்ட விஷயத்தின் மீதான தங்கள் ஒப்புதலை பதிவு செய்து, முறையாக கூட்டப்பட்ட கூட்டத்தில் ஒரு நிறுவனத்தின் board of directors வழங்கும் முறையான எழுத்துப்பூர்வ முடிவு.',
  'memorandum-of-association': 'ஒரு நிறுவனத்தின் பெயர், பதிவு செய்யப்பட்ட அலுவலகம், நோக்கங்கள் அல்லது குறிக்கோள், மற்றும் அது நடத்த அனுமதிக்கப்பட்ட செயல்பாடுகளின் வரம்பை வரையறுக்கும், நிறுவன இணைப்பின் போது தாக்கல் செய்யப்படும் அடிப்படை ஆவணம். இந்த ஆவணம் அனுமதிப்பதற்கு வெளியே பொதுவாக ஒரு நிறுவனம் செயல்பட முடியாது.',
  'articles-of-association': 'பங்குதாரர்களின் உரிமைகள், இயக்குநர்களின் அதிகாரங்கள், கூட்டங்கள் நடத்தப்படும் விதம் போன்ற விஷயங்களை உள்ளடக்கி, ஒரு நிறுவனம் எவ்வாறு நடத்தப்படுகிறது என்பதை நிர்வகிக்கும் உள் விதிகளை வரையறுக்கும் ஆவணம். இது Memorandum of Association உடன் இணைந்து செயல்படுகிறது, ஆனால் நிறுவனத்தின் நோக்கத்தை விடவும் உள் நிர்வாகத்தைக் கையாளுகிறது.',
  'share-transfer-deed': 'ஒரு நிறுவனத்தின் பங்குகளை ஒரு பங்குதாரரிடமிருந்து மற்றொருவருக்கு முறையாக மாற்ற பயன்படுத்தப்படும், Form SH-4 என்ற நிர்ணயிக்கப்பட்ட படிவம். நிறுவனம் அந்த மாற்றத்தைப் பதிவு செய்வதற்கு முன், இது உரிய முத்திரையிடப்பட்டு, மாற்றுபவர் மற்றும் பெறுபவர் இருவராலும் கையெழுத்திடப்பட்டிருக்க வேண்டும்.',
  'llp-agreement': 'ஒரு Limited Liability Partnership-இன் பங்குதாரர்களுக்கிடையேயும், பங்குதாரர்களுக்கும் LLP-க்குமிடையேயும் உள்ள ஒப்பந்தம்; ஒவ்வொரு பங்குதாரரின் மூலதனப் பங்களிப்பு, லாபப் பங்கீட்டு விகிதம், மற்றும் நிர்வாக உரிமைகள் மற்றும் கடமைகள் போன்ற விஷயங்களை இது வரையறுக்கிறது.',
  'registrar-of-companies': 'Ministry of Corporate Affairs-இன் கீழ் செயல்படும், நிறுவனங்கள் மற்றும் LLP-களைப் பதிவு செய்வதற்கும், ஒரு குறிப்பிட்ட மாநிலம் அல்லது பிராந்தியத்தில் அவற்றின் தொடர்ச்சியான இணக்கத் தாக்கல்களை மேற்பார்வை செய்வதற்கும் பொறுப்பான அரசு அதிகாரி.',
  'director-identification-number': 'இந்தியாவில் ஒரு நிறுவனத்தின் இயக்குநராக நியமிக்கப்படுவதற்கு முன் ஒவ்வொரு தனிநபரும் பெற வேண்டிய தனித்துவமான அடையாள எண். அந்த நபர் இயக்குநராக இருக்கும் அனைத்து நிறுவனங்களிலும் இந்த எண் அவருடனே தொடரும்.',
  'winding-up': 'ஒரு நிறுவனத்தை மூடும் சட்ட செயல்முறை, இதில் அதன் சொத்துகள் சேகரிக்கப்பட்டு, கடன்கள் தீர்க்கப்பட்டு, மீதமுள்ள எதேனும் தொகை பங்குதாரர்களுக்குள் விநியோகிக்கப்படும்; இதன் பிறகே நிறுவனம் இறுதியாகக் கலைக்கப்பட்டு பதிவேட்டிலிருந்து நீக்கப்படும்.',
  'e-form': 'Ministry of Corporate Affairs-இன் ஆன்லைன் போர்ட்டல் மூலம் Registrar of Companies-இடம் தாக்கல் செய்யப்படும் மின்னணு படிவம்; இயக்குநரை நியமிப்பது, பதிவு செய்யப்பட்ட அலுவலகத்தை மாற்றுவது, அல்லது ஆண்டறிக்கைகளைத் தாக்கல் செய்வது போன்ற வழக்கமான இணக்கத் தாக்கல்களுக்கு இது பயன்படுத்தப்படுகிறது.',
  'statutory-register': 'ஒரு நிறுவனம் சட்டப்படி பராமரிக்க வேண்டிய பதிவேடு, இதில் அதன் பங்குதாரர்கள், இயக்குநர்கள், அல்லது அதன் சொத்துகள் மீதான charge போன்ற குறிப்பிட்ட தகவல் இருக்கும். இந்தப் பதிவேடுகள் எப்போதும் புதுப்பிக்கப்பட்டிருக்க வேண்டும், மேலும் சட்டம் அனுமதிக்கும் சூழல்களில் பரிசோதனைக்காகத் திறந்திருக்க வேண்டும்.',
  'annual-general-meeting': 'பெரும்பாலான நிறுவனங்கள் ஒவ்வொரு நிதியாண்டுக்கும் ஒருமுறை நடத்த வேண்டிய கூட்டம், இதில் பங்குதாரர்கள் நிறுவனத்தின் ஆண்டு கணக்குகளை ஆராய்ந்து, dividend-ஐ அங்கீகரித்து, இயக்குநர்கள் மற்றும் தணிக்கையாளர்களை நியமிப்பது போன்ற விஷயங்களைக் கையாள்வர்.',
  'extraordinary-general-meeting': 'அடுத்த ஆண்டுக் கூட்டம் வரை காத்திருக்க முடியாத அவசர அல்லது குறிப்பிட்ட விஷயங்களைத் தீர்மானிக்க அழைக்கப்படும், Annual General Meeting அல்லாத ஒரு நிறுவனத்தின் பங்குதாரர்களின் எந்தக் கூட்டமும்.',
  'authorised-share-capital': 'அதன் Memorandum of Association-இல் குறிப்பிடப்பட்டுள்ளபடி, ஒரு நிறுவனம் பங்குதாரர்களுக்கு வெளியிட அனுமதிக்கப்பட்ட பங்குகளின் அதிகபட்ச மதிப்பு. இந்த வரம்பை மீறி பங்குகளை வெளியிடுவதற்கு முன் நிறுவனம் முறையாக இந்த வரம்பை உயர்த்த வேண்டும்.',
  'paid-up-share-capital': 'இதுவரை தங்களுக்கு வெளியிடப்பட்ட பங்குகளுக்கு ஈடாக பங்குதாரர்கள் நிறுவனத்திற்கு உண்மையில் செலுத்திய பணத் தொகை. நிறுவனம் வெளியிட அனுமதிக்கப்பட்ட மேல் வரம்பாகிய authorised share capital-ஐ விட இது குறைவாக இருக்கலாம்.',
  'certificate-of-incorporation': 'ஒரு நிறுவனம் சட்டப்படி உருவாக்கப்பட்டு பதிவு செய்யப்பட்டுள்ளது என்பதை உறுதிப்படுத்தும், Registrar of Companies வழங்கும் அதிகாரப்பூர்வ சான்றிதழ். இந்தச் சான்றிதழில் உள்ள தேதியிலிருந்து, நிறுவனத்தை நிறுவியவர்களிடமிருந்து தனித்துவமான ஒரு நிறுவனமாக அது சட்டப்படி உருவாகிறது.',
  'registered-office': 'Registrar of Companies-இடம் பதிவில் உள்ள நிறுவனத்தின் அதிகாரப்பூர்வ முகவரி, சட்ட அறிவிப்புகளையும் அதிகாரப்பூர்வ தொடர்புகளையும் பெற பயன்படுத்தப்படுகிறது. இது நிறுவனத்தின் முதன்மை வணிக இடமாக இருக்க வேண்டியதில்லை, ஆனால் அங்கு தொடர்புகளைப் பெற நிறுவனத்திற்கு வசதி இருக்க வேண்டும்.',
  'scheme-of-arrangement': 'இணைப்பு, பிரிப்பு, அல்லது கடன்கள் மீதான சமரசம் போன்ற நோக்கங்களுக்காகப் பயன்படுத்தப்படும், ஒரு நிறுவனத்திற்கும் அதன் பங்குதாரர்கள் அல்லது கடன் வழங்குநர்களுக்கும் இடையிலான ஏற்பாடு; National Company Law Tribunal-ஆல் அங்கீகரிக்கப்பட்டு, ஒப்புதல் பெற்றதும் அனைத்துத் தரப்பினருக்கும் கட்டுப்படுத்தும்.',
  'private-company': 'அதன் பங்குகளை பொது மக்களுக்கு சுதந்திரமாக வழங்க முடியாத, மற்றும் அதன் articles பங்குகளை மாற்றும் உரிமையைக் கட்டுப்படுத்தும் நிறுவனம்; பங்குகளை சுதந்திரமாக வர்த்தகம் செய்யக்கூடிய, பட்டியலிடப்பட்டிருந்தால் பங்குச் சந்தையில் வாங்கவும் விற்கவும் முடியும் public company-இலிருந்து இது வேறுபட்டது.',
  'one-person-company': 'ஒரு தனிநபர் மட்டுமே உருவாக்கி நடத்தக்கூடிய, அவரே அதன் ஒரே பங்குதாரராக இருக்கும் ஒரு வகை நிறுவனம்; இருந்தும், limited liability உள்ள தனித்துவமான சட்ட நிறுவனமாக இருக்கும் பலன் இந்த வணிகத்திற்குக் கிடைக்கும்.',
  'shareholder': 'ஒரு நிறுவனத்தில் பங்குகளை வைத்திருந்து, அந்த அளவுக்கு அதன் உரிமையாளர்களில் ஒருவராக இருக்கும் நபர்; பொதுக் கூட்டங்களில் வாக்களிப்பது, dividend பெறுவது போன்ற உரிமைகள் இவருக்கு உண்டு. நிறுவனத்தின் உறுப்பினர் (member) என்றும் இவர் அழைக்கப்படுவார்.',
  'director': 'ஒரு நிறுவனத்தின் விவகாரங்களை நிர்வகிக்கவும் அதன் பெயரில் முடிவுகள் எடுக்கவும், அதன் board-இல் நியமிக்கப்படும் நபர்; நல்லெண்ணத்துடனும் நிறுவனத்தின் நலன்களுக்கு முன்னுரிமை கொடுத்தும் செயல்பட வேண்டிய கடமை இவருக்கு உண்டு. ஒரு managing director அல்லது whole-time director என்பவர், board கூட்டங்களில் வெறுமனே கூடுவதைத் தாண்டி, குறிப்பிட்ட அன்றாட நிர்வாகப் பொறுப்புகளை வைத்திருப்பவர்.',
  'company-secretary': 'statutory register-களைப் பராமரிப்பது, கூட்டங்களை ஒழுங்கமைப்பது, Registrar of Companies-இடம் சரியான நேரத்தில் தாக்கல்கள் செய்யப்படுவதை உறுதி செய்வது உட்பட, நிறுவனச் சட்டத்தை நிறுவனம் பின்பற்றுவதற்குப் பொறுப்பான தகுதிபெற்ற நிபுணர்.',
  'auditor': 'ஒரு நிறுவனத்தின் நிதி அறிக்கைகளையும் கணக்குப் பதிவுகளையும் ஆராய்ந்து, நிறுவனத்தின் நிதி நிலையை அவை உண்மையாகவும் நியாயமாகவும் பிரதிபலிக்கின்றனவா என்பதை பங்குதாரர்களுக்கு அறிக்கை செய்ய, நிறுவனத்தால் நியமிக்கப்படும் சுயாதீன, தகுதிபெற்ற நிபுணர்.',
  'charge-company': 'கடனுக்குப் பிணையமாக, ஒரு கடன் வழங்குநருக்குச் சாதகமாக, நிறுவனத்தின் சொத்து அல்லது பெறத்தக்க தொகைகள் போன்ற சொத்துகள் மீது உருவாக்கப்படும் உரிமை. இது மற்றவர்களுக்கு எதிராக அமல்படுத்தப்படக்கூடியதாக இருக்க, நிர்ணயிக்கப்பட்ட காலத்திற்குள் இந்த charge-ஐ Registrar of Companies-இடம் பதிவு செய்ய நிறுவனம் கட்டாயப்படும்.',
  'dividend': 'ஒரு பொதுக் கூட்டத்தில் அறிவிக்கப்பட்ட பிறகு, அல்லது ஒரு இடைக்கால dividend-க்கு board-ஆல் அறிவிக்கப்பட்ட பிறகு, நிறுவனம் தனது பங்குதாரர்களுக்கு, பொதுவாக அவர்கள் வைத்திருக்கும் பங்குகளின் விகிதத்தில், விநியோகிக்கும் அதன் லாபத்தின் ஒரு பகுதி.',
  'quorum': 'board meeting, AGM, அல்லது EGM போன்ற ஒரு கூட்டம் செல்லுபடியாக நடத்தப்பட்டு, அதன் முடிவுகள் கட்டுப்படுத்தும் வகையில் இருக்க, கூட்டத்தில் கட்டாயம் இருக்க வேண்டிய குறைந்தபட்ச உறுப்பினர்கள் அல்லது இயக்குநர்களின் எண்ணிக்கை.',
  'proxy': 'ஒரு பங்குதாரர் தாமாகக் கூட்டத்தில் கூட முடியாதபோது, கையொப்பமிடப்பட்ட ஆவணம் மூலம், அவருக்காக ஒரு பொதுக் கூட்டத்தில் கூடி வாக்களிக்க அந்தப் பங்குதாரரால் அங்கீகரிக்கப்படும் நபர்.',
  'striking-off': 'செயலற்ற ஒரு நிறுவனத்தின் பெயரை, அதன் சொந்த விண்ணப்பத்தின் பேரிலோ விரைவு வெளியேற்றத்திற்காக, அல்லது அது வணிகம் நடத்தாதிருந்த நிலையில் Registrar-இன் சொந்த முன்னெடுப்பின் பேரிலோ, Registrar of Companies பதிவேட்டிலிருந்து நீக்கும் செயல்முறை.',
  'oppression-and-mismanagement': 'ஒரு நிறுவனத்தின் விவகாரங்கள் தங்களுக்கு ஒடுக்குமுறையாகவோ நிறுவனத்தின் சொந்த நலனுக்கே தீங்கு விளைவிக்கும் விதமாகவோ நடத்தப்படும்போது, National Company Law Tribunal-ஐ அணுக பங்குதாரர்களுக்கு, முதன்மையாக சிறுபான்மைப் பங்குதாரர்களுக்கு, கிடைக்கும் நிவாரணம்.',
  'shareholders-agreement': 'பங்குகளை எவ்வாறு மாற்றலாம், இயக்குநர்களை நியமிக்கும் உரிமைகள், முட்டுக்கட்டை ஏற்பட்டால் என்ன நடக்கும் போன்ற விஷயங்களை, Articles of Association-இல் பதிவாகியவற்றைத் தாண்டி வரையறுக்கும், ஒரு நிறுவனத்தின் சில அல்லது அனைத்து பங்குதாரர்களுக்கிடையேயான தனியார் ஒப்பந்தம்.',

  // ─── Property Law ─────────────────────────────────────────────────
  'sale-deed': 'ஒரு விலைக்கு ஈடாக, அசையா சொத்தின் உரிமையை விற்பவரிடமிருந்து வாங்குபவருக்கு முறையாக மாற்றும் சட்ட ஆவணம். உரிமத்தை மாற்றுவதில் சட்டப்படி செல்லுபடியாக இருக்க, இது முறையாக முத்திரையிடப்பட்டு பதிவு செய்யப்பட்டிருக்க வேண்டும்.',
  'gift-deed': 'ஒரு சொத்தின் உரிமையை, தாமாக முன்வந்து, எந்தப் பணமும் பெறாமல் ஒரு நபரிடமிருந்து மற்றொருவருக்கு மாற்றும் சட்ட ஆவணம். sale deed போலவே, சட்ட ரீதியாக செயல்படுவதற்கு இது முறையாக முத்திரையிடப்பட்டு பதிவு செய்யப்பட்டிருக்க வேண்டும்.',
  'lease-deed': 'சொத்தின் உரிமையை மாற்றாமல், வாடகைக்கு ஈடாக, ஒப்புக்கொள்ளப்பட்ட காலத்திற்கு வேறொருவரின் சொத்தை ஆக்கிரமித்துப் பயன்படுத்தும் உரிமையை ஒரு நபருக்கு வழங்கும் சட்ட ஆவணம்.',
  'mortgage-deed': 'ஒரு சொத்தின் உரிமையாளர், கடனுக்கோ மற்ற கடப்பாட்டுக்கோ பிணையமாகத் தமது சொத்தை அடைமானம் வைக்கும் சட்ட ஆவணம்; கடன் திருப்பிச் செலுத்தப்படாவிட்டால், அந்தச் சொத்தின் உடைமையை அவசியம் விட்டுக் கொடுக்காமலேயே, அதன் மீது சில உரிமைகளை கடன் வழங்குநருக்கு இது வழங்குகிறது.',
  'general-power-of-attorney': 'ஒரு குறிப்பிட்ட பணிக்கு மட்டும் வரையறுக்கப்படாமல், சொத்தை நிர்வகிப்பது, வங்கிக் கணக்குகளை இயக்குவது, சட்ட விவகாரங்களைக் கையாளுவது போன்ற பரந்த அளவிலான விஷயங்களில் ஒரு நபருக்காக செயல்பட மற்றொரு நபருக்கு அதிகாரம் அளிக்கும் ஆவணம்.',
  'special-power-of-attorney': 'பொது விவகாரங்களுக்காக அல்லாமல், ஒரு குறிப்பிட்ட சொத்தை விற்பது போன்ற ஒரே ஒரு குறிப்பிட்ட பணிக்காகவோ பரிவர்த்தனைக்காகவோ மட்டும் ஒரு நபருக்காக செயல்பட மற்றொரு நபருக்கு அதிகாரம் அளிக்கும் ஆவணம்.',
  'stamp-duty': 'sale deed அல்லது lease deed போன்ற சில ஆவணங்களை செயல்படுத்தும்போது மாநில அரசுக்குச் செலுத்த வேண்டிய வரி, பொதுவாக சொத்தின் மதிப்பு அல்லது பரிவர்த்தனைத் தொகையின் சதவீதமாக இருக்கும். சரியான stamp duty செலுத்தாமல், இத்தகைய ஆவணங்களை நீதிமன்றத்தில் செல்லுபடியான ஆதாரமாகப் பயன்படுத்தவோ பதிவு செய்யவோ பொதுவாக முடியாது.',
  'registration-of-document': 'sale deed அல்லது gift deed போன்ற ஒரு ஆவணத்தை அரசின் sub-registrar அலுவலகத்தில் பதிவு செய்யும் முறையான செயல்முறை. பதிவு செய்தல் பரிவர்த்தனையின் பொதுப் பதிவை உருவாக்குகிறது, மேலும் பல வகை சொத்து ஆவணங்களுக்கு, மாற்றத்தைச் செல்லுபடியாக்க இது சட்டப்படி அவசியம்.',
  'encumbrance': 'நிலுவையிலுள்ள அடைமானம் அல்லது நிலுவையிலுள்ள சட்டத் தகராறு போன்ற, ஒரு சொத்துடன் இணைக்கப்பட்ட கோரிக்கை, கடப்பாடு, அல்லது கட்டுப்பாடு; இது சொத்தை சுதந்திரமாக விற்கவோ மாற்றவோ உரிமையாளரின் திறனைப் பாதிக்கலாம்.',
  'title-deed': 'ஒரு சொத்தின் மீதான ஒரு நபரின் உரிமைக்கான சட்டச் சான்றாகச் செயல்படும் ஆவணம், எடுத்துக்காட்டாக அவரது பெயரில் உள்ள sale deed அல்லது gift deed. ஒரு சொத்தை உள்ளடக்கிய எந்தப் பரிவர்த்தனைக்கும் முன், அதற்கு சட்டப்படி உரிமையாளர் யார் என்பதை உறுதிப்படுத்த இது பரிசோதிக்கப்படும்.',
  'consideration-in-a-deed': 'ஒரு deed-இன் கீழ் மாற்றப்படும் சொத்து அல்லது உரிமைக்கு ஈடாகக் கொடுக்கப்படும் விலை, பணம், அல்லது பலன், எடுத்துக்காட்டாக ஒரு சொத்திற்காகச் செலுத்தப்பட்ட விற்பனை விலை. ஒரு deed, சம்பந்தப்பட்ட consideration-ஐ தெளிவாகக் குறிப்பிட வேண்டும்; ஒரு gift deed-இன் விஷயத்தில், எந்த consideration-ம் கொடுக்கப்படவில்லை என்று தெளிவாகக் குறிப்பிட வேண்டும்.',
  'encumbrance-certificate': 'ஒரு குறிப்பிட்ட காலத்தில், அடைமானங்கள் அல்லது நிலுவைக் கடப்பாடுகள் போன்ற பதிவு செய்யப்பட்ட ஏதேனும் encumbrance ஒரு சொத்தில் உள்ளதா என்பதை உறுதிப்படுத்தும், sub-registrar அலுவலகம் வழங்கும் அதிகாரப்பூர்வ சான்றிதழ். விற்பவருக்கு தெளிவான, விற்கத்தகுந்த உரிமம் உள்ளதா என்பதை உறுதிசெய்ய, சொத்து வாங்குவதற்கு முன் இது பொதுவாகச் சரிபார்க்கப்படும்.',
  'mutation-of-property': 'விற்பனை அல்லது வாரிசுரிமை போன்ற காரணங்களால் ஏற்படும் ஒரு சொத்தின் உரிமை மாற்றத்தைப் பிரதிபலிக்க, அரசு வருவாய்ப் பதிவுகளை புதுப்பிக்கும் செயல்முறை. Mutation தானாக உரிமையை மாற்றுவதில்லை; அது sale deed அல்லது மற்ற ஆவணம் மூலமே நடக்கிறது; ஆனால் சொத்து வரி போன்ற நோக்கங்களுக்காக அதிகாரப்பூர்வ நில பதிவுகளை இது புதுப்பித்து வைக்கிறது.',
  'easement': 'ஒரு சாலையை அடைய வழி உரிமை, அல்லது வெளிச்சம் அல்லது காற்று பெறும் உரிமை போன்ற, ஒரு வரையறுக்கப்பட்ட நோக்கத்திற்காக, அருகிலுள்ள மற்றொரு நபரின் சொத்தைப் பயன்படுத்த ஒரு சொத்தின் உரிமையாளருக்கு உள்ள உரிமை.',
  'lien': 'வேறொருவரின் சொத்தை வைத்திருக்கும், அல்லது அதற்குத் தொடர்பான பணம் தனக்குக் கொடுக்கப்பட வேண்டிய நபருக்கு, கடன் அல்லது கோரிக்கை தீர்க்கப்படும் வரை அந்தச் சொத்தின் உடைமையைத் தக்க வைக்கும் உரிமை.',
  'conveyance': 'ஒரு நபரிடமிருந்து மற்றொருவருக்கு சொத்தின் உரிமையை மாற்றுவதற்கான பொது சட்டச் சொல்; அந்த மாற்றத்தை நிறைவேற்றும் sale deed போன்ற ஆவணத்தையும் குறிக்க இது பயன்படும்.',
  'relinquishment-deed': 'ஒரு சொத்தின் இணை உரிமையாளர், மற்ற இணை உரிமையாளர்களில் ஒருவருக்கோ அதற்கு மேற்பட்டவருக்கோ சாதகமாக, அதில் தனது பங்கைத் துறக்கும் ஆவணம்; உறவினர்களுக்குள் வாரிசாகக் கிடைத்த குடும்பச் சொத்தைத் தீர்க்க இது பெரும்பாலும் பயன்படுத்தப்படுகிறது.',
  'will': 'ஒரு நபர், தமது மறைவுக்குப் பிறகு தமது சொத்து எவ்வாறு விநியோகிக்கப்பட வேண்டும் என்பதை வரையறுக்கும் சட்ட ஆவணம். இது பொதுவாக உருவாக்கியவரின் மறைவின் போதே மட்டும் செயல்படும், மேலும் அதற்கு முன் எந்த நேரத்திலும் அவரால் மாற்றப்படலாம் அல்லது ரத்து செய்யப்படலாம்.',
  'probate': 'ஒரு will உண்மையானது மற்றும் செல்லுபடியானது என உறுதிப்படுத்தி, அதில் பெயரிடப்பட்ட executor-க்கு இறந்தவரின் சொத்துக்களை அதற்கேற்ப நிர்வகிக்க அங்கீகாரம் வழங்கும், தகுதியான நீதிமன்றம் வழங்கும் சான்றிதழ்.',
  'succession-certificate': 'ஒரு நபர் will இல்லாமல் இறந்துள்ள சூழலில், இறந்தவருக்குக் கிடைக்க வேண்டிய வங்கி இருப்பு அல்லது பங்குகள் போன்ற கடன்களையும் பத்திரங்களையும் வசூலிக்கவும், அவற்றுக்கு செல்லுபடியான ரசீது வழங்கவும் அல்லது அவற்றை மாற்றவும் வைத்திருப்பவருக்கு அங்கீகாரம் வழங்கும், நீதிமன்றம் வழங்கும் சான்றிதழ்.',
  'letters-of-administration': 'ஒரு நபர் will இல்லாமலோ executor-ஐ பெயரிடாமலோ இறந்துள்ள சூழலில், இறந்தவரின் சொத்துக்களை வசூலிக்கவும், நிர்வகிக்கவும், விநியோகிக்கவும் ஒரு administrator-ஐ நியமிக்கும், நீதிமன்றம் வழங்கும் அங்கீகாரம்.',
  'legal-heir-certificate': 'இறந்த ஒரு நபரின் சட்ட வாரிசுகளைக் குறிப்பிடும், வருவாய் அல்லது நகராட்சி அதிகாரம் வழங்கும் சான்றிதழ்; பெரிய அல்லது தகராறான கோரிக்கைகளுக்கான succession certificate-க்கு விரைவான மாற்றாக, பயன்பாட்டு இணைப்புகளை மாற்றுதல் அல்லது சிறிய நிலுவைத் தொகைகளைக் கோருதல் போன்ற எளிய நோக்கங்களுக்கு இது பொதுவாகப் பயன்படுத்தப்படுகிறது.',
  'khata-patta': 'வெவ்வேறு மாநிலங்களில் Khata அல்லது Patta எனப் பல பெயர்களில் அறியப்படும், உள்ளூர் நகராட்சி அல்லது வருவாய் அதிகாரம் பராமரிக்கும் பதிவு, சொத்து வரி மதிப்பீடு போன்ற நோக்கங்களுக்காக ஒரு குறிப்பிட்ட சொத்துக்கு எதிராக ஒரு நபரின் பெயரைக் காட்டுகிறது. இது உடைமை அல்லது வரிக் கடப்பாட்டை இந்த அதிகாரங்கள் தாமாக அங்கீகரிக்கும் பதிவே தவிர, அதுவே உரிமைக்கான சான்று அல்ல.',
  'adverse-possession': 'உண்மையான உரிமையாளரின் அனுமதியின்றி, வேறொருவரின் சொத்தில் வெளிப்படையாகவும், தொடர்ச்சியாகவும், விரோதமாகவும் போதுமான நீண்ட காலம் உடைமையில் இருந்த ஒரு நபர், அதற்கான சட்ட உரிமத்தைப் பெற்று, அசல் உரிமையாளரின் கோரிக்கையை முறியடிக்கும் சட்டக் கோட்பாடு.',
  'benami-transaction': 'ஒரு நபரின் பெயரில் சொத்து வாங்கப்படும், ஆனால் அதற்கான பணத்தை, அதன் பலன்களை உண்மையில் அனுபவிக்கும் மற்றொரு நபரே செலுத்தும் பரிவர்த்தனை; ஆவணங்களில் பெயரிடப்பட்ட நபர், உண்மையான வாங்குபவருக்காக மட்டுமே அதை வைத்திருப்பவராக இருப்பார். இத்தகைய பரிவர்த்தனைகள் பொதுவாகத் தடைசெய்யப்பட்டுள்ளன, மேலும் சட்டம் அங்கீகரிக்கும் வரையறுக்கப்பட்ட விதிவிலக்குகளுக்கு உட்பட்டு, அரசு அந்தச் சொத்தைப் பறிமுதல் செய்யலாம்.',
  'landlord-and-tenant': 'landlord என்பவர், lease அல்லது வாடகை ஒப்பந்தத்தின் கீழ், உரிமையை மாற்றாமல், வாடகைக்கு ஈடாக, ஒப்புக்கொள்ளப்பட்ட காலத்திற்கு மற்றொரு நபரான tenant-ஐ ஆக்கிரமித்துப் பயன்படுத்த அனுமதிக்கும் சொத்தின் உரிமையாளர்.',
  'mortgagor-and-mortgagee': 'mortgagor என்பவர், ஒரு mortgage deed-இன் கீழ் கடனுக்குப் பிணையமாக தமது சொத்தை அடைமானம் வைக்கும் உரிமையாளர். mortgagee என்பவர், அந்தப் பிணையம் யாருக்குச் சாதகமாக உருவாக்கப்பட்டதோ அந்தக் கடன் வழங்குநர்; mortgagor கடனைத் திருப்பிச் செலுத்தத் தவறினால், சொத்தின் மீதான தனது உரிமைகளை இவர் அமல்படுத்தலாம்.',
  'attestation': 'ஒரு நபர் ஒரு ஆவணத்தைச் செயல்படுத்துவதைத் தாங்கள் கண்டோம் என்றும் கையெழுத்து உண்மையானது என்றும் உறுதிப்படுத்தும் சாட்சிகள், ஒரு will அல்லது சில deed-கள் போன்ற ஆவணத்தில் கையெழுத்திடுவது. தேவைப்படும் எண்ணிக்கையிலான சாட்சிகளால் attest செய்யப்பட்டால் மட்டுமே சில ஆவணங்கள் சட்டப்படி செல்லுபடியாகும்.',
  'circle-rate': 'மாநில அரசால் அறிவிக்கப்படும், ஒரு குறிப்பிட்ட பகுதியில் உள்ள சொத்து அதிகாரப்பூர்வமாக மதிப்புள்ளதாகக் கருதப்படும் ஒரு யூனிட் பரப்புக்கான குறைந்தபட்ச மதிப்பு; தரப்பினருக்கிடையே ஒப்புக்கொள்ளப்பட்ட உண்மையான விற்பனை விலை குறைவாக இருந்தாலும், stamp duty கணக்கிடுவதற்கான அடித்தளமாக இது பயன்படுத்தப்படும்.',

  // ─── Latin Maxims ─────────────────────────────────────────────────
  'res-judicata': 'ஒரே தரப்பினருக்கிடையே ஒரு தகுதியுள்ள நீதிமன்றம் ஒரு விஷயத்தை ஏற்கெனவே இறுதியாகத் தீர்த்துவிட்டால், அதை மீண்டும் வழக்காடுவதைத் தடுக்கும் விதி. ஏற்கெனவே முடிவாகத் தீர்க்கப்பட்ட பிரச்சினைகளை முடிவில்லாமல் மீண்டும் மீண்டும் வழக்காடுவதை இது தடுக்கிறது.',
  'sub-judice': 'தற்போது நீதிமன்றத்தில் நிலுவையில் இருந்து, இன்னும் தீர்க்கப்படாத ஒரு விஷயம். sub judice நிலையில் உள்ள ஒரு விஷயம் குறித்து பகிரங்கமாகக் கருத்துத் தெரிவிப்பதோ முன்கூட்டியே முடிவு கூறுவதோ சில சமயங்களில் நீதிமன்ற அவமதிப்பாக ஆகலாம்.',
  'ultra-vires': 'ஒரு நிறுவனம் தனது Memorandum of Association-இல் குறிப்பிடப்பட்டுள்ள நோக்கங்களுக்கு வெளியே செயல்படுவது, அல்லது ஓர் அரசு அதிகாரம் சட்டத்தால் தனக்கு வழங்கப்பட்ட அதிகாரங்களை மீறுவது போன்று, ஒரு நபர் அல்லது அமைப்பு தனது சட்டப்பூர்வ அதிகாரத்திற்கு அப்பால் செய்யும் செயல். ultra vires செயல் பொதுவாக செல்லுபடியற்றதாகக் கருதப்படும்.',
  'mens-rea': 'ஒரு செயல் குற்றமாகக் கருதப்படுவதற்கு, அதைச் செய்யும்போது ஒரு நபருக்கு பொதுவாக இருந்திருக்க வேண்டிய, எண்ணம் அல்லது அறிவு போன்ற குற்ற மனநிலை. பெரும்பாலான குற்றவியல் குற்றங்களுக்கு, குற்றமான செயலையும் இந்தக் குற்ற மனநிலையையும் இரண்டையும் வழக்குத் தொடுப்பவர் நிரூபிக்க வேண்டும்.',
  'actus-reus': 'ஒரு குற்றத்தை உருவாக்கும் உடல்சார் செயல் அல்லது நடத்தை; அதற்குப் பின்னால் உள்ள மனநிலையான mens rea-விலிருந்து இது வேறுபட்டது. குற்றம் சாட்டப்பட்டவர் இந்தக் குற்றமான செயலை உண்மையில் செய்தார் என்பதை பெரும்பாலான குற்றங்களுக்கு வழக்குத் தொடுப்பவர் நிரூபிக்க வேண்டும்.',
  'audi-alteram-partem': 'முதலில் நியாயமான வாய்ப்பு அளித்து தங்கள் தரப்பை முன்வைக்க அனுமதிக்காமல், எவரும் தீர்ப்பளிக்கப்படவோ தண்டிக்கப்படவோ கூடாது என்ற கோட்பாடு. நீதிமன்றங்களும் தீர்ப்பாயங்களும் பின்பற்றும் இயல்பு நீதியின் அடிப்படை விதிகளில் இதுவும் ஒன்று.',
  'caveat-emptor': 'வாங்குபவர், தமது வாங்குதலை முடிப்பதற்கு முன் தாம் வாங்கும் பொருளின் தரத்தையும் நிலையையும் சரிபார்க்கும் பொறுப்புடையவர் என்ற கோட்பாடு. விற்பவர்கள் மீதும் கடமைகளை வைக்கும் நுகர்வோர் பாதுகாப்புச் சட்டத்தால், இந்தியாவில் இதன் பயன்பாடு பெரிதும் குறுகியுள்ளது.',
  'bona-fide': 'நேர்மையாகவும், நல்லெண்ணத்துடனும், ஏமாற்ற வேண்டும் என்ற எண்ணமில்லாமலும் செய்யப்படுவது. நேர்மை அல்லது உண்மையான நம்பிக்கை முடிவைப் பாதிக்கும் சூழல்களில் குறிப்பாக, தகராறுகளைத் தீர்மானிக்கும்போது ஒரு தரப்பினரின் நடத்தை bona fide-ஆக இருந்ததா என்பதை நீதிமன்றங்கள் பெரும்பாலும் கருத்தில் கொள்கின்றன.',
  'mala-fide': 'bona fide நடத்தைக்கு மாறாக, நேர்மையற்ற அல்லது முறையற்ற நோக்கத்துடன், கெட்ட எண்ணத்துடன் செய்யப்படுவது. ஒரு தனிப்பட்ட பகையைத் தீர்க்க எடுக்கப்பட்ட அதிகாரப்பூர்வ முடிவு போன்ற, mala fide-ஆக எடுக்கப்பட்ட ஒரு நடவடிக்கை, அது தொழில்நுட்ப அடிப்படையில் அந்த நபரின் அதிகார வரம்பிற்குள் இருந்தாலும், நீதிமன்றத்தால் தள்ளுபடி செய்யப்படலாம்.',
  'prima-facie': 'முகத்தோற்றத்தில், அல்லது விஷயம் முழுமையாக விரிவாக ஆராயப்படுவதற்கு முன், கிடைக்கும் பொருள்களை முதலில் பார்த்த அடிப்படையில். அறிவிப்பு வெளியிடுதல் அல்லது இடைக்கால உத்தரவு வழங்குதல் போன்ற சில படிகளை எடுப்பதற்கு முன், ஒரு prima facie வழக்கு இருப்பதை நீதிமன்றம் பெரும்பாலும் திருப்தியடைய வேண்டும்.',
  'suo-motu': 'செயல்படுமாறு கோரி எவரும் முறையான வேண்டுகோளோ புகாரோ தாக்கல் செய்யாமலேயே, ஒரு நீதிமன்றமோ அதிகாரமோ தனது சொந்த முன்னெடுப்பில் எடுக்கும் நடவடிக்கை.',
  'obiter-dicta': 'ஒரு வழக்கைத் தீர்மானிப்பதற்கு அவசியமில்லாத, ஒரு நீதிபதி தீர்ப்பில் தெரிவிக்கும் கருத்துகள் அல்லது கணிப்புகள்; முடிவின் கட்டுப்படுத்தும் பகுதியை உருவாக்கும் உண்மையான காரணமான ratio decidendi-விலிருந்து இவை வேறுபட்டவை. obiter dicta பிற்கால வழக்குகளில் நம்பகத்தன்மையுடையதாக இருக்கலாம், ஆனால் முன்னுதாரணமாகக் கட்டுப்படுத்தாது.',
  'ratio-decidendi': 'ஒரு வழக்கில் தனது முடிவை எட்ட நீதிமன்றம் நம்பியிருக்கும் அடிப்படை சட்டக் காரணமும் கோட்பாடும்; தற்செயலான கருத்துகளான obiter dicta-விலிருந்து இது வேறுபட்டது. தீர்ப்பில் உள்ள ஒவ்வொரு கூற்றும் அல்ல, இந்தக் காரணமே பிற்கால வழக்குகளுக்கு கட்டுப்படுத்தும் முன்னுதாரணமாக ஆகிறது.',
  'ab-initio': 'ஆரம்பத்திலிருந்தே. ஒரு ஒப்பந்தம் அல்லது நியமனம் போன்றவை, நீதிமன்றம் பின்னர் அவ்வாறு அறிவித்த நேரத்திலிருந்து அல்லாமல், அவை உருவாக்கப்பட்ட தருணத்திலிருந்தே செல்லுபடியற்றவை அல்லது வெற்றிடமானவை எனக் கருதப்படுவதை விவரிக்க இது பெரும்பாலும் பயன்படுத்தப்படுகிறது.',
  'in-personam': 'முழு உலகையும் நோக்கிய உரிமையான in rem-க்கு மாறாக, ஒரு குறிப்பிட்ட நபரை நோக்கி இயக்கப்பட்டு, அந்த நபரை மட்டுமே கட்டுப்படுத்தும் உரிமை அல்லது நீதிமன்ற உத்தரவு.',
  'in-rem': 'ஒரு குறிப்பிட்ட நபரை மட்டும் கட்டுப்படுத்தும் உரிமையான in personam-க்கு மாறாக, ஒரு சொத்து அல்லது அந்தஸ்து போன்ற ஒரு பொருளைப் பற்றிய, முழு உலகையும் கட்டுப்படுத்தும் உரிமை அல்லது நீதிமன்ற உத்தரவு.',
  'per-incuriam': 'பொதுவாக நீதிமன்றம் கடைபிடிக்க வேண்டிய ஒரு கட்டுப்படுத்தும் முன்னுதாரணத்தையோ தொடர்புடைய சட்டப் பிரிவையோ கவனிக்காமல் விட்டதால் ஏற்படும், கவனக்குறைவான ஒரு முடிவு. per incuriam எனக் கண்டறியப்படும் ஒரு தீர்ப்பு, அந்தப் புள்ளியில் கட்டுப்படுத்தும் முன்னுதாரணமாகக் கருதப்படாது.',
  'stare-decisis': 'ஒத்த ஒவ்வொரு வழக்கையும் புதிதாக முடிவு செய்வதற்குப் பதிலாக, முந்தைய முடிவுகள், குறிப்பாக மேல் நீதிமன்றங்களின் முன்னுதாரணங்களை நீதிமன்றங்கள் பின்பற்ற வேண்டும் என்ற கோட்பாடு. சட்டம் பயன்படுத்தப்படும் விதத்தில் நிலைத்தன்மையையும் முன்கூட்டியே அறியக்கூடிய தன்மையையும் இது வளர்க்கிறது.',
  'habeas-corpus': 'அரசியலமைப்பின் Article 32 அல்லது Article 226-இன் கீழ் பிறப்பிக்கப்படும் ஆணை, ஒரு நபரைக் காவலில் வைத்திருக்கும் நபரையோ அதிகாரத்தையோ, அந்த நபரை நீதிமன்றத்தில் முன்வைத்து காவலுக்கான காரணத்தை நியாயப்படுத்துமாறு பணிக்கிறது. சட்டவிரோதமான அல்லது தன்னிச்சையான தடுப்புக்காவலுக்கு எதிரான முதன்மை நிவாரணம் இதுவாகும்.',
  'mandamus': 'அரசியலமைப்பின் Article 32 அல்லது Article 226-இன் கீழ் பிறப்பிக்கப்படும் ஆணை, ஒரு பொது அதிகாரத்தையோ அதிகாரியையோ, அவர் செய்யத் தவறிய அல்லது செய்ய மறுத்த ஒரு பொதுக் கடமையைச் செய்யுமாறு பணிக்கிறது.',
  'certiorari': 'அரசியலமைப்பின் Article 32 அல்லது Article 226-இன் கீழ் பிறப்பிக்கப்படும் ஆணை; இதன் மூலம் ஒரு மேல் நீதிமன்றம், கீழமை நீதிமன்றம் அல்லது தீர்ப்பாயத்திடமிருந்து ஒரு வழக்கின் பதிவை வரவழைத்து, அது அதிகார வரம்பு இல்லாமலோ இயல்பு நீதியை மீறியோ வழங்கப்பட்டிருந்தால் அதன் உத்தரவை ரத்து செய்கிறது.',
  'quo-warranto': 'அரசியலமைப்பின் Article 32 அல்லது Article 226-இன் கீழ் பிறப்பிக்கப்படும் ஆணை; ஒரு நபர் எந்த அதிகாரத்தின் அடிப்படையில் ஒரு பொது பதவியை வைத்திருக்கிறார் என்பதைக் கேள்விக்குள்ளாக்கி, சட்ட உரிமையின்றி அதை வைத்திருப்பதாகக் கண்டறியப்பட்டால் அவரை அதிலிருந்து நீக்குகிறது.',
  'amicus-curiae': 'ஒரு வழக்கில் தரப்பினர் அல்லாத ஒரு நபர் அல்லது அமைப்பு, பொதுவாக பொது முக்கியத்துவமுள்ள விஷயத்தில், வழக்குக்குத் தொடர்புடைய தகவல், நிபுணத்துவம், அல்லது வாதங்களை வழங்கி நீதிமன்றத்திற்கு உதவ அனுமதிக்கப்படுபவர்.',
  'de-facto': 'முறையாகவோ சட்டப்படியோ அங்கீகரிக்கப்பட்டதா இல்லையா என்பதைப் பொருட்படுத்தாமல், நடைமுறையிலோ உண்மையிலோ இருப்பது. சட்டப்படி இருப்பதைக் குறிக்கும் "de jure"-உடன் இது பெரும்பாலும் வேறுபடுத்திக் காட்டப்படும்.',
  'de-jure': 'நடைமுறையில் உண்மையில் என்ன நடக்கிறது என்பதைப் பிரதிபலிக்கிறதா இல்லையா என்பதைப் பொருட்படுத்தாமல், சட்டப்படியோ சட்ட உரிமையின் அடிப்படையிலோ இருப்பது. உண்மையில் இருப்பதைக் குறிக்கும் "de facto"-உடன் இது பெரும்பாலும் வேறுபடுத்திக் காட்டப்படும்.',
  'inter-alia': 'மற்ற விஷயங்களுடன். ஒரு பட்டியல் அல்லது அறிக்கை முழுமையானது அல்ல என்பதைக் குறிக்க, அதாவது குறிப்பாகக் குறிப்பிடப்பட்டவை தவிர வேறு விஷயங்களும் உள்ளன என்பதைக் காட்ட இது பயன்படுத்தப்படுகிறது.',
  'ipso-facto': 'அந்த உண்மையினாலேயே, ஒரு குறிப்பிட்ட முடிவையோ விளைவையோ ஏற்படுத்த வேறு எதுவும் தேவையில்லாமல்.',
  'quid-pro-quo': 'ஒப்பிடத்தக்க மதிப்புள்ள மற்றொன்றுக்கு ஈடாகக் கொடுக்கப்படும் அல்லது செய்யப்படும் ஒன்று. எடுத்துக்காட்டாக, ஓர் ஒப்பந்தத்தின் தரப்பினருக்கிடையே கடந்து செல்லும் consideration-ஐ விவரிக்க ஒப்பந்தச் சட்டத்தில் இது பயன்படுத்தப்படுகிறது.',
  'status-quo': 'ஒரு குறிப்பிட்ட நேரத்தில் நிலவும் இருப்பு நிலை. வழக்கு நிலுவையில் இருக்கும்போது தரப்பினர் யாரும் தற்போதைய நிலையை மாற்றாமல் இருக்க, "status quo-ஐ பராமரிக்க" நீதிமன்றங்கள் பெரும்பாலும் இடைக்கால உத்தரவுகளை வழங்குகின்றன.',
  'pari-passu': 'முன்னுரிமையின்றி, சமமான அடிப்படையில். கடன் வழங்குநர்கள் அல்லது கோரிக்கையாளர்கள் விகிதாசாரமாகச் செலுத்தப்படும் அல்லது நடத்தப்படும் சூழல்களில், மற்றவர்களுக்கு மேல் யார்க்கும் முன்னுரிமை கொடுக்கப்படாமல் இருக்கும்போது இது முதன்மையாகப் பயன்படுத்தப்படுகிறது.',
  'res-ipsa-loquitur': 'பொருளே தனக்காகத் தானே பேசுகிறது. முதன்மையாக அலட்சியம் தொடர்பான வழக்குகளில் பயன்படுத்தப்படுகிறது; ஒரு விபத்தின் சூழ்நிலைகள், அலட்சியத்தை இவ்வளவு வெளிப்படையாகக் காட்டுவதால், அது எப்படி நடந்தது என்பதை மேலும் நிரூபிக்க வேண்டிய அவசியமில்லாமல், அந்த உண்மைகளே அலட்சியத்திற்கான ஆதாரமாகக் கருதப்படும்.',
  'ejusdem-generis': 'சட்டப் பொருள் விளக்கத்தின் ஒரு விதி: ஒரு சட்டம் குறிப்பிட்ட பொருட்களைப் பட்டியலிட்டு, அதைத் தொடர்ந்து பொது வார்த்தைகளைக் கொண்டிருந்தால், அந்தப் பொது வார்த்தைகள் பட்டியலிடப்பட்ட பொருட்களின் அதே வகையைச் சேர்ந்தவற்றுக்கு மட்டுமே வரையறுக்கப்பட்டதாகப் படிக்கப்படும், எதையும் உள்ளடக்குவதாக அல்ல.',
  'noscitur-a-sociis': 'சட்டப் பொருள் விளக்கத்தின் ஒரு விதி: ஒரு சட்டத்தில் உள்ள தெளிவற்ற ஒரு சொல் அல்லது தொடரின் பொருளை, அதைச் சுற்றியுள்ள சொற்களைப் பார்த்து புரிந்துகொள்ள முடியும்; ஏனெனில் ஒரு சொல் அதனுடன் இருக்கும் சொற்களின் தொடர்பால் அறியப்படுகிறது.',
  'doli-incapax': 'குற்றம் செய்யும் திறனற்றவர். முதன்மையாக சிறு குழந்தைகளுக்காகப் பயன்படுத்தப்படுகிறது; ஒரு குறிப்பிட்ட வயதிற்குக் கீழே, தங்கள் செயல்களுக்கு குற்றவியல் பொறுப்பேற்க வேண்டிய புரிதல் அவர்களுக்கு இல்லை என்று சட்டம் முன்கூட்டியே கருதுகிறது.',
  'uberrima-fides': 'மிக உன்னதமான நல்லெண்ணம். காப்பீட்டு ஒப்பந்தங்கள் போன்ற சில ஒப்பந்தங்களில், பெரும்பாலான ஒப்பந்தங்களுக்குப் பொருந்தும் தவறாகக் குறிப்பிடாமல் இருக்கும் வழக்கமான கடமையைத் தாண்டி, ஒவ்வொரு தரப்பினரும் அனைத்து முக்கிய உண்மைகளையும் மற்றவருக்குத் தாமாக முன்வந்து வெளிப்படுத்த வேண்டும்.',
  'de-novo': 'புதியதாக, அல்லது மீண்டும் தொடங்குவது. "de novo" விசாரணை அல்லது வழக்கு என்றால், முந்தைய நடவடிக்கை நடக்காததைப் போல, வெறுமனே பிழைகளுக்காக மீள்பரிசீலனை செய்யப்படாமல், விஷயம் ஆரம்பத்திலிருந்து மீண்டும் விசாரிக்கப்படுகிறது என்று பொருள்.',
  'functus-officio': 'தனது கடமையையோ அதிகாரத்தையோ நிறைவேற்றிவிட்டதால், அந்த விஷயத்தில் மேலும் செயல்பட அதிகாரம் இல்லாதது. எடுத்துக்காட்டாக, ஏற்கெனவே ஒரு final decree வழங்கிய நீதிமன்றம், பெரும்பாலான விஷயங்களில், அந்த வழக்கைப் பொருத்தவரை functus officio ஆகும்.',
  'sui-generis': 'தன்னளவில் ஒரு தனித்த வகை, அல்லது தனித்துவமானது — ஏற்கெனவே உள்ள ஒரு வகைப்பாட்டிற்குள்ளோ வகைமைக்குள்ளோ சரியாகப் பொருந்தாததால், தனக்கென தனித்துவமான சட்ட நடத்தை தேவைப்படுவது.',
  'lis-pendens': 'நிலுவையிலுள்ள வழக்கு அல்லது வழக்காடுதல். lis pendens கோட்பாட்டின் கீழ், நடைமுறையிலுள்ள ஒரு வழக்கின் பொருளாக இருக்கும் சொத்தை, அந்த வழக்கில் மற்ற தரப்பினரின் உரிமைகளைப் பாதிக்கும் விதத்தில் மாற்ற முடியாது.',
  'pendente-lite': 'வழக்காடுதல் நிலுவையில் இருக்கும்போது. இடைக்கால காப்பனுசரணை அல்லது பாதுகாப்பு உரிமை போன்ற, வழக்கு இறுதியாகத் தீரும் வரை அந்த காலத்திற்கு மட்டும் பொருந்தும் உத்தரவு, உரிமை, அல்லது ஏற்பாட்டை விவரிக்கப் பயன்படுகிறது.',
  'ex-post-facto': 'செயல் நடந்த பிறகு. சட்டம் தானே இயற்றப்பட்ட தேதிக்கு முன்பிருந்தே அமலுக்கு வரும் வகையில், ஒரு செயலைக் குற்றமாக்க அல்லது அதற்கான தண்டனையை அதிகரிக்க முயலும் சட்டத்திற்கு பெரும்பாலும் பயன்படுத்தப்படுகிறது — குற்றவியல் விஷயங்களில் இதை அரசியலமைப்பு பொதுவாகத் தடை செய்கிறது.',
  'nunc-pro-tunc': 'இப்போதைக்காக அன்று. நீதிமன்றம் இப்போது பிறப்பிக்கும், ஆனால் முன்பிருந்த ஒரு தேதியிலிருந்தே சட்ட ரீதியாக அமலுக்கு வரும் உத்தரவு; ஒரு தாமதமோ தவறுதலோ இல்லையெனில் ஒரு தரப்பினரின் உரிமைகளை நியாயமற்ற முறையில் பாதிக்கும் சூழலில், பதிவைச் சரிசெய்ய வழக்கமாகப் பயன்படுத்தப்படும்.',
  'quantum-meruit': 'ஒருவர் எவ்வளவு சம்பாதித்தாரோ அவ்வளவு. எந்த நிலையான விலையும் ஒப்புக்கொள்ளப்படாதபோது, அல்லது ஒப்பந்தத்தை முடிக்க முடியாத நிலையில், damages கோரிக்கைக்குப் பதிலாக, செய்த வேலைக்கோ வழங்கிய சேவைக்கோ நியாயமான பணம் கோரும் வாதம்.',
  'bona-vacantia': 'உரிமையாளரற்ற சொத்து. கலைக்கப்பட்ட ஒரு நிறுவனத்தின் சொத்துகள் அல்லது வாரிசுகளோ will-ஓ இல்லாமல் இறந்த ஒரு நபரின் சொத்துகள் போன்ற, அடையாளம் காண முடியாத உரிமையாளருள்ள சொத்து; இது சட்டப்படி அரசுக்குச் சென்றடையும்.',
  'modus-operandi': 'செயல்படும் ஒரு குறிப்பிட்ட முறை அல்லது வடிவம். குற்றவியல் விஷயங்களில், ஒரு குற்றம் நிகழ்த்தப்படும் தனித்துவமான முறையைக் குறிக்கும்; இது சில சமயங்களில் ஒரு குற்றம் சாட்டப்பட்டவரை முந்தைய ஒத்த குற்றங்களுடன் தொடர்புபடுத்த உதவலாம்.',
  'coram-non-judice': 'நீதிபதி அல்லாத ஒருவர் முன்பாகவோ, விஷயத்தை விசாரிக்க அதிகாரமில்லாத நீதிமன்றம் முன்பாகவோ. coram non judice-ஆக வழங்கப்படும் ஒரு உத்தரவு, ஆரம்பத்திலேயே முறையான அதிகார வரம்பின்றி வழங்கப்பட்டதால், செல்லுபடியற்றதாகக் கருதப்படும்.',
  'mutatis-mutandis': 'தேவையான மாற்றங்களைச் செய்த பின். ஒரு சூழலுக்காக எழுதப்பட்ட ஒரு விதி, பிரிவு, அல்லது ஏற்பாட்டை, அவசியம் வேறுபட வேண்டிய விவரங்களை மட்டும் சரிசெய்து, மற்றொரு ஒத்த சூழலுக்குப் பயன்படுத்தும்போது இது பயன்படுத்தப்படுகிறது.',
  'sine-die': 'மீண்டும் தொடங்க நிலையான தேதி இல்லாமல். "sine die" ஒத்திவைக்கப்படும் ஒரு விசாரணை அல்லது விஷயம், அடுத்து எப்போது எடுத்துக்கொள்ளப்படும் என்று குறிப்பிட்ட தேதி எதுவும் நிர்ணயிக்காமல், காலவரையறையின்றி ஒத்திவைக்கப்படுகிறது.',
  'sine-qua-non': 'இல்லாவிட்டால் ஒன்று நடக்கவோ இருக்கவோ முடியாத, இன்றியமையாத ஒரு நிபந்தனை. ஒரு குறிப்பிட்ட விளைவுக்கு முற்றிலும் தவிர்க்க முடியாத தேவையை விவரிக்கப் பயன்படுகிறது.',
  'nemo-judex-in-causa-sua': 'எவரும் தமது சொந்த வழக்கில் நீதிபதியாக இருக்கக்கூடாது. ஒரு விஷயத்தைத் தீர்மானிக்கும் நபர் அல்லது அதிகாரத்திற்கு, அதன் விளைவில் தனிப்பட்ட நாட்டம் இருக்கக்கூடாது என்று கோரும், இயல்பு நீதியின் அடிப்படைக் கோட்பாடு.',
  'volenti-non-fit-injuria': 'இணங்கும் ஒரு நபருக்கு, எந்த தீங்கும் ஏற்படுவதில்லை. முதன்மையாக tort சட்டத்தில் பயன்படும் ஒரு பாதுகாப்பு வாதம்; தெரிந்தே, தாமாக முன்வந்து தீங்கின் அபாயத்தை ஏற்றுக்கொண்ட ஒரு நபர், பின்னர் அந்தத் தீங்குக்கு இழப்பீடு கோர முடியாது.',
};
